-- ====================================================================
-- SejarahWira  |  ERA 5:   |  seed_era5.sql
-- 3 naratif (8 + 8 + 8 = 24 babak), setiap babak ada 1 quest dan satu "Giliran Anda", serta bank soalan era.
-- Babak mengikut peristiwa dan sub-topik (bukan kuota). Setiap naratif merangkumi semua sub-topik Unit 1:
-- idea awal (1887, 1938, 1951, 1955), empat sebab, Adelphi, lawatan Sarawak dan JSKM, Cobbold dan laporannya,
-- JAK, referendum Singapura, Perjanjian London, UNMM, Pemasyhuran, cabaran dan kesan.
-- Misi setiap babak diuji daripada dialog dan latar babak itu sendiri.
--
-- Pelajar MERASUK jasad tokoh sebenar: Naratif 1 = Tunku (NPC 1), Naratif 2 = Donald Stephens (NPC 3),
-- Naratif 3 = Tun Ghazali Shafie (NPC 10). Baris dialog npcID NULL ialah baris "Pemain" yang dituturkan tokoh peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran, 3 = pengenalan peranan.
-- Setiap quest ada "aftermath" (akibat jika salah) dan "turns" (Giliran Anda). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Jalankan SELEPAS seed.sql:
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era5.sql
-- Selamat dijalankan berulang kali (kandungan Era 5 lama dipadam dahulu). Era lain tidak disentuh.
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 5 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 5;

-- 2. NPC: nama fail gambar mengikut folder npc sebenar.
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (1 Susun Garis Masa, 2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 5 (43 soalan aneka pilihan, ID 501-543)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 5;


COMMIT;
