INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(81, 'Pengkaji Budaya', 'Pengkaji yang mengembara dengan buku nota lapangan untuk mengenali agama dan kepercayaan rakyat Malaysia.', 'Mencatat agama dan kepercayaan dengan adil dan hormat supaya semua kaum saling memahami.', 'ahli_antropologi_UNESCO.png'),
(82, 'Bobohizan Penjaga Padi', 'Bobohizan yang menjaga upacara semangat padi dan memimpin para penjaga adat (watak rekaan).', 'Menurunkan cerita kepercayaan setiap kaum kepada generasi muda dengan penuh hormat.', 'bobohizan.png'),
(83, 'Lemambang Penyair', 'Lemambang yang membaca jampi mentera dan melagukan puji-pujian kepada Petara (watak rekaan).', 'Menjaga syair dan upacara supaya kepercayaan setiap kaum difahami dan dihormati.', 'lemambang.png'),
(84, 'Aishah', 'Gadis Muslim yang peramah dan petah bertanya (watak rekaan).', 'Mewakili penganut Islam dalam perbualan antara agama.', 'gadis_melayu.png'),
(85, 'Daniel', 'Pemuda Kristian dari Sarawak yang mesra dan suka bergurau (watak rekaan).', 'Mewakili penganut Kristian dalam perbualan antara agama.', 'orang_sarawak.png'),
(86, 'Mei Ling', 'Gadis Buddha yang lembut tetapi bijak berjenaka (watak rekaan).', 'Mewakili penganut Buddha dalam perbualan antara agama.', 'amoi_cina.png'),
(87, 'Kavitha', 'Gadis Hindu yang ceria dan gemar bercerita (watak rekaan).', 'Mewakili penganut Hindu dalam perbualan antara agama.', 'gadis_india.png'),
(88, 'Harjit', 'Pemuda Sikh yang tenang dan ramah (watak rekaan).', 'Mewakili penganut Sikh dalam perbualan antara agama.', 'jejaka_india.png'),
(89, 'Kenny', 'Pemuda yang mengamalkan Ajaran Tao dan Ajaran Konfusius, suka bergurau (watak rekaan).', 'Mewakili penganut Ajaran Tao dan Ajaran Konfusius dalam perbualan antara agama.', 'lengchai_cina.png'),
(90, 'Tok Batin Temiar', 'Orang tua Orang Asli suku Temiar yang tenang dan bijaksana (watak rekaan).', 'Mewakili kepercayaan Orang Asli suku Temiar dan Semai di Semenanjung.', 'orang_tradisi_lama.png'),
(91, 'Pak Mah Meri', 'Lelaki suku Mah Meri yang ramah dan pandai berseloroh (watak rekaan).', 'Mewakili suku Mah Meri dan upacara Puja Pantai.', 'mah_meri.png'),
(92, 'Apai Jelani', 'Orang tua Iban yang mesra dan pandai bercerita (watak rekaan).', 'Mewakili masyarakat Iban dan upacara Miring.', 'sarawakian.png'),
(93, 'Linda', 'Gadis Kadazandusun yang bersemangat dan petah bercerita (watak rekaan).', 'Mewakili masyarakat Kadazandusun dan Kinorohingan.', 'gadis_sabah.png'),
(94, 'Pak Tani Bisaya', 'Petani Bisaya di Sarawak yang peramah dan rajin (watak rekaan).', 'Mewakili masyarakat Bisaya dan upacara Tamarok.', 'petani.png'),
(95, 'Pak Bajau', 'Lelaki Bajau dari Sabah yang peramah dan suka menjamu tetamu (watak rekaan).', 'Mewakili masyarakat Bajau dengan upacara Ngeduang dan Mag\'ombo.', 'orang_bajau.png'),
(96, 'Tuanku Sultan', 'Ketua negeri bergelar Sultan yang juga Ketua Agama Islam di negerinya (watak rekaan).', 'Menerangkan kedudukan Raja sebagai Ketua Agama Islam di negeri beraja.', 'sultan.png'),
(97, 'Yang di-Pertua Negeri', 'Ketua negeri yang dilantik, dari negeri tanpa Raja (watak rekaan).', 'Menerangkan kedudukan Yang di-Pertuan Agong sebagai Ketua Agama Islam di Melaka, Pulau Pinang, Sabah dan Sarawak.', 'yang_dipertuan_negeri.png'),
(98, 'Murid Sekolah', 'Murid yang gemar bertanya dan sentiasa ingin tahu (watak rekaan).', 'Mewakili generasi muda yang belajar menghormati agama dan kepercayaan lain.', 'budak_gajet.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(501, 'Nota Lapangan Tujuh Pintu', 5, 'Masuki peranan seorang pengkaji budaya dengan buku nota lapangan. Dalam setiap misi kau mengenali agama dan ajaran di Malaysia, pengasas, kitab suci dan rumah ibadat.'),
(502, 'Persidangan Para Penjaga Adat', 5, 'Masuki peranan Bobohizan yang dijemput ke persidangan para penjaga adat. Kau belajar tentang animisme dan kepercayaan Orang Asli, Iban, Bisaya, Bajau dan Kadazandusun.'),
(503, 'Syair Seribu Kepercayaan', 5, 'Masuki peranan Lemambang yang melagukan syair di Pesta Kepercayaan Sekolah. Dalam setiap bait kau mengenali kedudukan agama dalam Perlembagaan, rumah ibadat dan adab di dalamnya.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e5_n1_s1', 'Sebuah lorong dengan masjid, gereja, kuil, tokong dan gurdwara berdekatan. Enam sahabat sedang menyusun kad pengasas agama untuk projek sekolah, namun kad-kad itu bercampur.', 1, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s2', 'Perpustakaan kecil di tengah lorong. Enam kitab dan buku terletak di atas meja, namun label rak tercabut. Seorang pelawat hampir meletakkan Bible di rak al-Quran.', 2, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s3', 'Seorang kanak-kanak bertanya kepada Kavitha tentang kepercayaan agamanya. Sekeping kad tentang kepercayaan Hindu terletak di tangan.', 3, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s4', 'Satu pameran kecil tentang Ajaran Konfusius dan Ajaran Tao. Kenny menunjukkan dua buku berbeza, namun pengunjung selalu mengatakan kedua-duanya sama.', 4, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s5', 'Dewan seminar kecil. Papan putih bertulis tiga perkataan, iaitu pemerintah, pedagang dan golongan agama. Seorang murid keliru bagaimanakah agama-agama ini sampai ke Malaysia.', 5, 501, 'bangunan_perlembagaan.png'),
('e5_n1_s6', 'Tiga kad terjatuh dari buku nota. Rukun Islam dan Rukun Iman, hari Ahad di gereja, dan Waheguru. Pengkaji ingin menyusun semula agar setiap agama dipadankan dengan amalan benar.', 6, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s7', 'Satu jalan dengan enam rumah ibadat berdekatan, iaitu masjid, gereja, tokong, wat, kuil dan gurdwara. Pelancong asing mengambil gambar namun tidak mengenali nama setiap rumah ibadat.', 7, 501, 'tempat_beribadat_berdekat.png'),
('e5_n1_s8', 'Senja di lorong yang sama. Enam sahabat duduk di bangku sambil berfikir mengapakah agama penting dalam kehidupan. Kad refleksi terletak di tengah bulatan.', 8, 501, 'tempat_beribadat_semua.png'),
('e5_n2_s1', 'Tepi pantai di Pulau Carey. Penghulu kampung berdiri di hadapan seorang murid yang bertanya mengapakah penduduk mempercayai gua dan batu besar mempunyai roh.', 1, 502, 'mah_meri_puja_pantai.png'),
('e5_n2_s2', 'Upacara Puja Pantai di Pulau Carey. Orang kampung berarak ke pantai dengan persembahan. Tok Batin Temiar tiba dengan satu soalan tentang tujuan upacara.', 2, 502, 'mah_meri_puja_pantai.png'),
('e5_n2_s3', 'Rumah panjang di Sarawak. Lemambang membaca jampi mantera di hadapan sajian. Seorang tetamu bertanya kepada Apai Jelani siapakah yang dipuja dalam upacara ini.', 3, 502, 'upacara_miring.png'),
('e5_n2_s4', 'Sebuah ladang baharu di Sarawak. Pak Tani Bisaya membaca jampi mantera sebelum memulakan kerja. Seorang pesakit terbaring di rumah berhampiran sedang menunggu upacara.', 4, 502, 'tamarok_bisaya.png'),
('e5_n2_s5', 'Pantai barat Sabah. Keluarga si mati menyediakan jamuan untuk tetamu. Seorang pelajar bertanya mengapakah upacara Bajau di Semporna pula bernama lain.', 5, 502, 'ngeduang.png'),
('e5_n2_s6', 'Pesta Kaamatan di perkarangan rumah tradisi. Linda memegang kad Kinorohingan dan Magavau. Seorang tetamu bertanya apakah peranan Bobohizan dalam upacara.', 6, 502, 'kinorohingan.png'),
('e5_n2_s7', 'Perkampungan Bajau di atas air, Semporna. Perahu berhias dan gerbang upacara menyambut pelawat. Pelancong ingin tahu tempat untuk berjumpa petunjuk upacara Mag''ombo dan Ngeduang.', 7, 502, 'upacara_pantai.png'),
('e5_n2_s8', 'Bulatan terakhir di persidangan. Lima penjaga adat berdiri di hadapan lima kad dan diminta berkongsi siapakah mengetuai upacara masing-masing.', 8, 502, 'mah_meri_puja_pantai.png'),
('e5_n3_s1', 'Dewan Pesta Kepercayaan Sekolah. Empat kad kronologi tentang kedudukan Islam dalam Perlembagaan terletak di atas pentas. Seorang guru bimbang urutannya terbalik.', 1, 503, 'bangunan_perlembagaan.png'),
('e5_n3_s2', 'Papan kenyataan Perlembagaan. Tuanku Sultan dan Yang di-Pertua Negeri berdiri bersebelahan, seorang murid keliru siapakah Ketua Agama Islam bagi negeri masing-masing.', 2, 503, 'bangunan_perlembagaan.png'),
('e5_n3_s3', 'Satu kempen kesedaran di luar Bangunan Perlembagaan. Seorang pemuda berbual dengan guru, katanya kebebasan beragama tidak wujud di negara ini. Seorang pelajar memegang kad Perkara 11.', 3, 503, 'bangunan_perlembagaan.png'),
('e5_n3_s4', 'Kawasan tumpuan pelancong. Enam rumah ibadat berselerak mengikut kad pameran. Pelancong asing hendak masuk, namun tidak tahu nama atau adab yang benar.', 4, 503, 'tempat_beribadat_semua.png'),
('e5_n3_s5', 'Pameran masjid tertua. Tiga papan kenyataan Masjid Negara, Masjid Kampung Laut dan Masjid Al-Qadim berselerak. Pelajar hendak menulis laporan namun kad bercampur.', 5, 503, 'tempat_beribadat_semua.png'),
('e5_n3_s6', 'Pameran rumah ibadat lain. Sekeping papan Gereja St. Michael, Wat Boonyaram, Tokong Cheng Hoon Teng, kuil kaca dan Wadda Gurdwara berselerak. Rakan-rakan membahaskan mana yang tertua.', 6, 503, 'tempat_beribadat_berdekat.png'),
('e5_n3_s7', 'Sebuah kumpulan murid bersiap melawat semua rumah ibadat. Guru memeriksa pakaian dan tingkah laku, namun seorang murid bertanya mengapakah perlu menjaga adab di tempat ibadat kaum lain.', 7, 503, 'tempat_beribadat_semua.png'),
('e5_n3_s8', 'Hujung lawatan. Enam rakan berhimpun di perkarangan sekolah untuk menulis rumusan. Papan putih bertulis, iaitu mengapakah menghormati kepelbagaian agama menjamin perpaduan?', 8, 503, 'tempat_beribadat_semua.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(501, 'e5_n1_s1', 'Kad Pengasas Agama', 'Padankan agama dan ajaran dengan pengasas atau asas ajarannya.', '4', 'Mengenal pasti pengasas dan asas agama: Islam, Kristian, Buddha, Sikh, Ajaran Konfusius dan Ajaran Tao.', '{"pairs": [{"text": "Islam", "pair": 1}, {"text": "Menyembah Allah Yang Maha Esa", "pair": 1}, {"text": "Kristian", "pair": 2}, {"text": "Dibawa oleh Jesus Christ", "pair": 2}, {"text": "Buddha", "pair": 3}, {"text": "Diasaskan oleh Siddharta Gautama", "pair": 3}, {"text": "Sikh", "pair": 4}, {"text": "Diasaskan oleh Guru Nanak", "pair": 4}, {"text": "Ajaran Konfusius", "pair": 5}, {"text": "Diasaskan oleh Kung Fu Tze", "pair": 5}, {"text": "Ajaran Tao", "pair": 6}, {"text": "Diasaskan oleh Lao Tzu", "pair": 6}], "aftermath": "Kad tersilap padan dan projek sekolah mencatat pengasas yang salah. Sahabat-sahabat tersinggung.", "turns": [{"after": 7, "options": [{"text": "Setiap agama mempunyai pengasas dan asas sendiri, jadi catatan mesti betul.", "isCorrect": true, "reaction": "Betul. Kami berasa dihormati."}, {"text": "Sebenarnya, semua agama sama sahaja, jadi tidak perlu catat dan lupakan sahaja.", "isCorrect": false, "reaction": "Aishah menggeleng. Perbezaan itulah yang perlu dihormati."}, {"text": "Cukup mencatat satu agama sahaja, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Sahabat-sahabat lain terkilan kerana agama mereka diabaikan."}], "clue": "Setiap agama ada pengasas sendiri."}]}'),
(502, 'e5_n1_s2', 'Rak Kitab Suci', 'Padankan kitab suci atau buku dengan agamanya.', '4', 'Mengenal pasti kitab suci: al-Quran (Islam), Bible (Kristian), Tipitaka (Buddha), Veda (Hindu), Sri Guru Granth Sahib (Sikh), Tao Te Ching (Tao).', '{"pairs": [{"text": "Al-Quran dan Hadis", "pair": 1}, {"text": "Agama Islam", "pair": 1}, {"text": "Bible", "pair": 2}, {"text": "Agama Kristian", "pair": 2}, {"text": "Tipitaka", "pair": 3}, {"text": "Agama Buddha", "pair": 3}, {"text": "Veda", "pair": 4}, {"text": "Agama Hindu", "pair": 4}, {"text": "Sri Guru Granth Sahib", "pair": 5}, {"text": "Agama Sikh", "pair": 5}, {"text": "Tao Te Ching", "pair": 6}, {"text": "Ajaran Tao", "pair": 6}], "aftermath": "Kitab terletak di rak yang salah dan label bertukar. Seorang penganut tersinggung melihat kitab sucinya salah letak.", "turns": [{"after": 7, "options": [{"text": "Rasanya, kitab suci perlu diletakkan di tempat yang betul sebagai tanda hormat kepada penganutnya.", "isCorrect": true, "reaction": "Betul. Itu tanda hormat kepada agama kami."}, {"text": "Bagi aku, letak sahaja kitab di mana-mana, jadi tidak payah difikirkan panjang dan biarkan sahaja.", "isCorrect": false, "reaction": "Penganut tersinggung. Kitab suci wajar dihormati."}, {"text": "Bagi aku, kitab suci hanya buku biasa, kerana tiada siapa yang akan peduli dan itu bukan urusan kita.", "isCorrect": false, "reaction": "Daniel menggeleng. Bible kitab suci kami."}], "clue": "Hormati kitab suci setiap agama."}]}'),
(503, 'e5_n1_s3', 'Kad Hukum Karma', 'Baca kad dan tentukan kepercayaan penganut agama Hindu.', '5', 'Memahami agama Hindu: percaya Hukum Karma dan kelahiran semula selepas mati; kitab suci Veda.', '{"clueText": "Kad: Penganut agama ini mempercayai Hukum Karma yang berkaitan dengan kelakuan manusia semasa hidup dan kelahiran semula selepas mati. Kitab sucinya dikenali sebagai Veda.", "options": [{"text": "Hukum Karma dan kelahiran semula selepas mati.", "isCorrect": true}, {"text": "Empat Kebenaran Mulia dan Jalan Lapan Lapis Mulia.", "isCorrect": false, "consequence": "Itu ajaran Buddha. Kavitha mengangkat kening."}, {"text": "Beribadat di gereja setiap hari Ahad.", "isCorrect": false, "consequence": "Itu amalan penganut Kristian. Kad dikembalikan."}, {"text": "Percaya kepada satu Tuhan bernama Waheguru.", "isCorrect": false, "consequence": "Itu kepercayaan Sikh. Kavitha tersenyum nipis."}], "aftermath": "Kad tersalah baca dan kanak-kanak itu mengejek kepercayaan Kavitha. Mereka bertengkar.", "turns": [{"after": 5, "options": [{"text": "Kita tidak mengejek kerana setiap agama mengajar perkara baik dan perlu dihormati.", "isCorrect": true, "reaction": "Betul. Kavitha tersenyum lega."}, {"text": "Kita boleh mengejek sedikit sahaja, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Kavitha terdiam dan menunduk."}, {"text": "Kita abaikan sahaja kepercayaan itu, jadi cukup dibiarkan begitu sahaja dan lupakan sahaja.", "isCorrect": false, "reaction": "Kanak-kanak lain tidak belajar apa-apa tentang kawan mereka."}], "clue": "Hormati kepercayaan setiap agama."}]}'),
(504, 'e5_n1_s4', 'Kad Ajaran Konfusius', 'Baca kad dan tentukan prinsip moral dalam Ajaran Konfusius.', '5', 'Memahami Ajaran Konfusius: prinsip moral tinggi seperti perikemanusiaan, kesusilaan dan ketaatan kepada ibu bapa; terkandung dalam buku Analek. Ajaran Tao: keharmonian dengan alam semesta.', '{"clueText": "Kad: Penganut ajaran ini percaya ajarannya menekankan prinsip moral yang tinggi seperti perikemanusiaan, kesusilaan dan ketaatan kepada ibu bapa. Ajaran ini terkandung dalam buku Analek dan diasaskan oleh Kung Fu Tze.", "options": [{"text": "Ajaran Konfusius.", "isCorrect": true}, {"text": "Ajaran Tao.", "isCorrect": false, "consequence": "Ajaran Tao diasaskan oleh Lao Tzu dan menekankan keharmonian dengan alam semesta. Kenny menggeleng."}, {"text": "Agama Hindu.", "isCorrect": false, "consequence": "Agama Hindu berkaitan Hukum Karma dan Veda. Kad dikembalikan."}, {"text": "Agama Kristian.", "isCorrect": false, "consequence": "Agama Kristian dibawa oleh Jesus Christ. Kenny tersenyum sedikit."}], "aftermath": "Kad tersalah baca dan Konfusius dikatakan sama dengan Tao. Kenny berasa ajaran mereka tidak dihargai.", "turns": [{"after": 6, "options": [{"text": "Kedua-dua ajaran berbeza, jadi kita perlu menghormati perbezaan itu.", "isCorrect": true, "reaction": "Itu yang kami harapkan."}, {"text": "Menurut aku, kedua-duanya sama sahaja, tidak perlu dibezakan.", "isCorrect": false, "reaction": "Kenny kecewa. Perbezaan itu penting."}, {"text": "Salah satu ajaran lebih baik daripada yang lain, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Perbandingan itu menyinggung penganut yang berbeza."}], "clue": "Hormati perbezaan ajaran."}]}'),
(505, 'e5_n1_s5', 'Nota Penyebaran Agama', 'Baca nota dan tentukan cara penyebaran agama di Malaysia.', '5', 'Memahami agama disebarkan melalui peranan pemerintah, pedagang dan golongan agama.', '{"clueText": "Nota: Terdapat pelbagai agama di Malaysia seperti agama Islam, Kristian, Buddha, Hindu dan Sikh. Terdapat juga ajaran Konfusius dan Tao. Penyebaran agama tersebut berlaku dengan pelbagai cara.", "options": [{"text": "Melalui peranan pemerintah, pedagang dan golongan agama.", "isCorrect": true}, {"text": "Melalui perang dan paksaan sahaja.", "isCorrect": false, "consequence": "Pernyataan itu tiada dalam nota. Murid mengerutkan dahi."}, {"text": "Melalui pasar malam sahaja.", "isCorrect": false, "consequence": "Jawapan itu mengelirukan dan tidak berasas."}, {"text": "Melalui hadiah wang kepada rakyat.", "isCorrect": false, "consequence": "Nota tidak menyebut hadiah wang. Kau diminta membaca semula."}], "aftermath": "Nota tersalah baca dan murid menyangka agama tersebar melalui paksaan. Sahabat-sahabat tersinggung.", "turns": [{"after": 7, "options": [{"text": "Agama tersebar melalui pelbagai cara yang aman, dan itu patut kita hormati.", "isCorrect": true, "reaction": "Betul. Kami berasa lega."}, {"text": "Agama tersebar kerana paksaan dan tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Murid-murid bertengkar sesama sendiri."}, {"text": "Menurut aku, agama tersebar secara kebetulan, lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Cikgu menggeleng kerana ada sebab dan cara yang jelas."}], "clue": "Penyebaran melalui cara yang aman."}]}'),
(506, 'e5_n1_s6', 'Amalan Setiap Agama', 'Padankan agama atau ajaran dengan amalan atau kepercayaannya.', '4', 'Mengenal pasti amalan dan kepercayaan: Islam (Rukun Islam dan Rukun Iman), Kristian (Ahad), Sikh (Waheguru), Buddha (Empat Kebenaran Mulia), Tao (Tao jalan).', '{"pairs": [{"text": "Islam", "pair": 1}, {"text": "Dua teras: Rukun Islam dan Rukun Iman", "pair": 1}, {"text": "Kristian", "pair": 2}, {"text": "Ahad dikhaskan untuk aktiviti keagamaan di gereja", "pair": 2}, {"text": "Sikh", "pair": 3}, {"text": "Percaya kepada satu Tuhan bernama Waheguru", "pair": 3}, {"text": "Buddha", "pair": 4}, {"text": "Empat Kebenaran Mulia dan Jalan Lapan Lapis Mulia", "pair": 4}, {"text": "Ajaran Tao", "pair": 5}, {"text": "Tao bermaksud jalan, hidup harmoni dengan alam", "pair": 5}], "aftermath": "Kad tersilap dan amalan satu agama diletakkan pada agama lain. Rakan-rakan terasa dipinggirkan.", "turns": [{"after": 6, "options": [{"text": "Amalan setiap agama berbeza, dan kita perlu memahaminya supaya dapat menghormati.", "isCorrect": true, "reaction": "Betul, itu membantu kami hidup aman."}, {"text": "Amalan agama lain tidak perlu dipelajari, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Rakan-rakan terasa disisih."}, {"text": "Amalan semua agama sama sahaja, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Itu salah, dan kau dibetulkan oleh rakan-rakan."}], "clue": "Fahami amalan agama lain untuk menghormati."}]}'),
(507, 'e5_n1_s7', 'Cari Enam Rumah Ibadat', 'Cari rumah ibadat bagi Islam, Kristian, Buddha, Konfusius dan Tao, Hindu dan Sikh.', '2', 'Mengenal pasti nama rumah ibadat: masjid, gereja, tokong, wat, kuil dan gurdwara.', '{"bgImage": "../assets/gameAsset/background/tempat_beribadat_berdekat.png", "hotspots": [{"name": "Masjid: rumah ibadat bagi penganut Islam", "top": "66.3%", "left": "17.2%"}, {"name": "Gereja: rumah ibadat bagi penganut Kristian", "top": "62.4%", "left": "33%"}, {"name": "Tokong: rumah ibadat Konfusius dan Tao, juga Buddha", "top": "60.4%", "left": "50.8%"}, {"name": "Wat atau tokong: rumah ibadat bagi penganut Buddha", "top": "61.6%", "left": "61.7%"}, {"name": "Kuil: rumah ibadat bagi penganut Hindu", "top": "62%", "left": "71.5%"}, {"name": "Gurdwara: rumah ibadat bagi penganut Sikh", "top": "66.3%", "left": "88%"}], "aftermath": "Nama rumah ibadat tersalah sebut dan pelancong menyebarkan maklumat yang salah.", "turns": [{"after": 6, "options": [{"text": "Menurut aku, setiap agama ada rumah ibadat tersendiri, dan kita perlu menghormati semuanya.", "isCorrect": true, "reaction": "Betul. Pelancong pun mengangguk."}, {"text": "Menurut aku, semua rumah ibadat sama sahaja namanya, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Pelancong terus tersilap dan ketawa kecil."}, {"text": "Sebenarnya, rumah ibadat tidak penting, kerana tiada siapa yang akan peduli dan lupakan sahaja.", "isCorrect": false, "reaction": "Rumah ibadat ialah tempat aktiviti keagamaan, bukan perkara remeh."}], "clue": "Hormati setiap rumah ibadat."}]}'),
(508, 'e5_n1_s8', 'Kad Refleksi Kepentingan Agama', 'Baca kad dan tentukan kepentingan amalan agama dan kepercayaan dalam kehidupan.', '5', 'Memahami kepentingan agama: menjadikan masyarakat maju, harmoni, berdisiplin dan mempunyai matlamat.', '{"clueText": "Kad: Amalan agama dan kepercayaan menjadikan masyarakat lebih maju, mewujudkan masyarakat yang hidup dalam suasana harmoni, memastikan masyarakat sentiasa berdisiplin dan memimpin masyarakat supaya mempunyai matlamat dalam kehidupan.", "options": [{"text": "Menjadikan masyarakat maju, harmoni, berdisiplin dan bermatlamat.", "isCorrect": true}, {"text": "Menjadikan masyarakat sentiasa berbalah.", "isCorrect": false, "consequence": "Rakan-rakan menggeleng. Jawapan itu bertentangan dengan kad."}, {"text": "Menjadikan masyarakat tidak berdisiplin.", "isCorrect": false, "consequence": "Kad menyebut sebaliknya. Kau dibetulkan."}, {"text": "Menjadikan masyarakat tiada matlamat hidup.", "isCorrect": false, "consequence": "Kad menyatakan agama memimpin masyarakat supaya bermatlamat."}], "aftermath": "Kad tersalah baca dan rakan-rakan menyangka agama tidak penting. Perbincangan berhenti begitu sahaja.", "turns": [{"after": 7, "options": [{"text": "Agama membimbing kita melakukan perkara baik, jadi masyarakat menjadi aman.", "isCorrect": true, "reaction": "Itu jawapan yang membuat kami bersetuju."}, {"text": "Rasanya, agama hanya menyusahkan hidup, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Rakan-rakan tersentak dan menggeleng."}, {"text": "Pada pendapat aku, agama tidak ada kaitan dengan masyarakat, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Cikgu menggeleng kerana kaitan itu jelas."}], "clue": "Agama membimbing masyarakat melakukan perkara baik."}]}'),
(509, 'e5_n2_s1', 'Kad Kepercayaan Alam', 'Baca kad dan tentukan nama kepercayaan yang menganggap alam mempunyai semangat dan roh nenek moyang.', '5', 'Memahami animisme: kepercayaan bahawa gua, pokok atau batu besar mempunyai semangat dan roh nenek moyang yang mesti dihormati.', '{"clueText": "Kad: Kepercayaan ini dipengaruhi oleh alam semesta. Masyarakat percaya bahawa gua, pokok atau batu besar mempunyai semangat dan roh nenek moyang yang mesti dihormati.", "options": [{"text": "Animisme.", "isCorrect": true}, {"text": "Konfusius.", "isCorrect": false, "consequence": "Konfusius ialah ajaran moral, bukan kepercayaan tentang semangat alam. Kad dikembalikan."}, {"text": "Hukum Karma.", "isCorrect": false, "consequence": "Hukum Karma ialah kepercayaan Hindu. Murid itu berkerut dahi."}, {"text": "Empat Kebenaran Mulia.", "isCorrect": false, "consequence": "Itu ajaran Buddha. Kad dikembalikan."}], "aftermath": "Kad tersalah baca dan kepercayaan alam diejek sebagai mengarut. Penduduk pantai tersinggung.", "turns": [{"after": 5, "options": [{"text": "Menurut aku, kepercayaan ini perlu dihormati kerana ia warisan nenek moyang mereka.", "isCorrect": true, "reaction": "Itu yang kami harapkan, nak."}, {"text": "Kepercayaan ini bodoh dan tidak masuk akal, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Penduduk kampung terdiam dan berpaling."}, {"text": "Rasanya, kepercayaan ini boleh dipaksa ditukar, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Bobohizan membantah. Tiada paksaan dalam menghormati kepercayaan."}], "clue": "Hormati kepercayaan nenek moyang."}]}'),
(510, 'e5_n2_s2', 'Dua Suku, Dua Upacara', 'Padankan suku Orang Asli dengan upacara dan tujuannya.', '4', 'Mengenal pasti kepercayaan Orang Asli: Mah Meri (Puja Pantai), Temiar dan Semai (upacara ritual), penyakit disebabkan kuasa jahat.', '{"pairs": [{"text": "Suku Mah Meri", "pair": 1}, {"text": "Puja Pantai: perlindungan dan pengampunan daripada semangat laut", "pair": 1}, {"text": "Suku Temiar dan Semai", "pair": 2}, {"text": "Upacara ritual menghalau kuasa jahat", "pair": 2}, {"text": "Kepercayaan Orang Asli", "pair": 3}, {"text": "Penyakit disebabkan oleh kuasa jahat", "pair": 3}], "aftermath": "Padanan tersilap dan kampung menyangka upacara satu suku boleh digantikan dengan suku lain. Tok Batin berasa disisih.", "turns": [{"after": 7, "options": [{"text": "Sebenarnya, setiap suku ada upacara dan sebab sendiri, jadi kita menghormati perbezaan itu.", "isCorrect": true, "reaction": "Itu jawapan yang baik, nak."}, {"text": "Bagi aku, upacara mereka sama sahaja, tidak perlu dipelajari, lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Tok Batin menggeleng. Perbezaan itu bermakna."}, {"text": "Bagi aku, upacara mereka lapuk dan patut ditinggalkan, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Pak Mah Meri berpaling muka dan tidak lagi bercakap."}], "clue": "Setiap suku ada upacara sendiri."}]}'),
(511, 'e5_n2_s3', 'Istilah Upacara Miring', 'Padankan istilah upacara Iban dengan maknanya.', '4', 'Memahami kepercayaan Iban: Petara (dewa), upacara Miring, Lemambang (penyair), jampi mantera.', '{"pairs": [{"text": "Petara", "pair": 1}, {"text": "Dewa yang menyampaikan petanda melalui mimpi dan bayangan", "pair": 1}, {"text": "Upacara Miring", "pair": 2}, {"text": "Upacara khusus untuk memuja Petara", "pair": 2}, {"text": "Lemambang", "pair": 3}, {"text": "Penyair yang melakukan upacara Miring", "pair": 3}, {"text": "Jampi mantera", "pair": 4}, {"text": "Bacaan permulaan upacara Miring", "pair": 4}], "aftermath": "Istilah tersilap padan dan tetamu menyangka Petara ialah nama tempat. Apai Jelani menggeleng.", "turns": [{"after": 4, "options": [{"text": "Petara ialah dewa yang dipuja, bukan nama tempat.", "isCorrect": true, "reaction": "Betul, nak. Kamu memahami kami."}, {"text": "Petara ialah nama kampung, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Apai Jelani ketawa kecil dan membetulkan."}, {"text": "Petara ialah alat muzik, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Lemambang menggeleng dan tersenyum nipis."}], "clue": "Petara ialah dewa."}]}'),
(512, 'e5_n2_s4', 'Nota Upacara Bisaya', 'Baca nota dan tentukan nama upacara yang menghalau kuasa ghaib daripada badan pesakit.', '5', 'Memahami kepercayaan Bisaya: jampi mantera ketika membuka kawasan pertanian baharu dan upacara Tamarok untuk menghalau kuasa ghaib daripada badan pesakit.', '{"clueText": "Nota: Masyarakat Bisaya di Sarawak bekerja sebagai petani dan mempercayai kuasa ghaib. Jampi mantera dibaca untuk mengelakkan gangguan kuasa ghaib semasa membuka kawasan pertanian baharu. Satu upacara diadakan untuk menghalau kuasa ghaib daripada badan pesakit.", "options": [{"text": "Upacara Tamarok.", "isCorrect": true}, {"text": "Upacara Miring.", "isCorrect": false, "consequence": "Miring ialah upacara Iban untuk memuja Petara. Nota dikembalikan."}, {"text": "Upacara Ngeduang.", "isCorrect": false, "consequence": "Ngeduang ialah upacara Bajau. Pak Tani Bisaya menggeleng."}, {"text": "Upacara Puja Pantai.", "isCorrect": false, "consequence": "Puja Pantai ialah upacara Mah Meri. Nota dikembalikan."}], "aftermath": "Nota tersalah baca dan pesakit dibiarkan tanpa upacara. Pak Tani Bisaya risau.", "turns": [{"after": 6, "options": [{"text": "Menurut aku, upacara itu dijalankan untuk menghalau kuasa ghaib daripada badan pesakit.", "isCorrect": true, "reaction": "Betul, nak. Pesakit itu berasa tenang."}, {"text": "Rasanya, upacara itu dijalankan untuk memanggil roh jahat, jadi orang lain tidak perlu tahu.", "isCorrect": false, "reaction": "Pak Tani Bisaya terkejut. Tujuannya sebaliknya."}, {"text": "Aku fikir upacara itu dijalankan untuk menjual hasil tani, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Jawapan itu tiada kaitan dengan upacara."}], "clue": "Menghalau kuasa ghaib daripada pesakit."}]}'),
(513, 'e5_n2_s5', 'Dua Wajah Upacara Bajau', 'Padankan upacara Bajau dengan lokasi dan maksudnya.', '4', 'Mengenal pasti upacara Bajau: Ngeduang (pantai barat, Kota Belud, jamuan sedekah) dan Mag''ombo (pantai timur, Semporna, menghargai warisan).', '{"pairs": [{"text": "Ngeduang", "pair": 1}, {"text": "Keluarga si mati menjamu tetamu sebagai sedekah", "pair": 1}, {"text": "Kota Belud", "pair": 2}, {"text": "Pantai barat Sabah, upacara Ngeduang", "pair": 2}, {"text": "Mag''ombo", "pair": 3}, {"text": "Menghargai dan menghormati warisan nenek moyang", "pair": 3}, {"text": "Semporna", "pair": 4}, {"text": "Pantai timur Sabah, upacara Mag''ombo", "pair": 4}], "aftermath": "Padanan tersilap dan pelajar menyangka Ngeduang dan Mag''ombo upacara yang sama. Pak Bajau berasa dipandang remeh.", "turns": [{"after": 6, "options": [{"text": "Bajau di pantai berlainan mempunyai upacara berbeza, tetapi kedua-duanya menghormati nenek moyang.", "isCorrect": true, "reaction": "Betul, Bobohizan. Terima kasih."}, {"text": "Kedua-dua upacara sama sahaja, kerana tiada siapa yang akan peduli dan lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Pak Bajau menggeleng dan membetulkan."}, {"text": "Upacara Bajau hanya wujud di Semporna, jadi cukup dibiarkan begitu sahaja dan itu lebih senang.", "isCorrect": false, "reaction": "Pak Bajau membetulkan. Ngeduang di Kota Belud juga ada."}], "clue": "Dua upacara berbeza, satu semangat."}]}'),
(514, 'e5_n2_s6', 'Istilah Kadazandusun', 'Padankan istilah kepercayaan Kadazandusun dengan maksudnya.', '4', 'Memahami kepercayaan Kadazandusun: Kinorohingan (Tuhan untuk meminta keselamatan dan perlindungan), Magavau (upacara semangat padi), Bobohizan (ketua bomoh).', '{"pairs": [{"text": "Kinorohingan", "pair": 1}, {"text": "Tuhan untuk meminta keselamatan dan perlindungan", "pair": 1}, {"text": "Magavau (Maga''au)", "pair": 2}, {"text": "Upacara semangat padi semasa Pesta Kaamatan", "pair": 2}, {"text": "Bobohizan", "pair": 3}, {"text": "Ketua bomoh yang mengetuai upacara", "pair": 3}], "aftermath": "Istilah tersilap dan tetamu salah faham tentang Kinorohingan. Linda terasa bangga kaumnya disalah sebut.", "turns": [{"after": 7, "options": [{"text": "Kinorohingan ialah Tuhan, dan upacara Magavau dijalankan semasa Pesta Kaamatan.", "isCorrect": true, "reaction": "Betul, Bobohizan. Linda tersenyum."}, {"text": "Kinorohingan ialah nama sebuah kampung, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Linda menggeleng dan membetulkan."}, {"text": "Bagi aku, magavau ialah pesta makanan sahaja, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Bobohizan membetulkan. Magavau berkaitan semangat padi."}], "clue": "Kinorohingan ialah Tuhan."}]}'),
(515, 'e5_n2_s7', 'Cari Petunjuk Upacara Bajau', 'Cari empat petunjuk upacara Bajau di perkampungan atas air.', '2', 'Memahami upacara Bajau: Mag''ombo (Semporna) dan Ngeduang (Kota Belud).', '{"bgImage": "../assets/gameAsset/background/upacara_pantai.png", "hotspots": [{"name": "Perahu berhias: Mag''ombo, upacara Bajau di Semporna", "top": "40.9%", "left": "77.6%"}, {"name": "Gerbang upacara: Mag''ombo menghargai warisan turun-temurun", "top": "46.1%", "left": "51.1%"}, {"name": "Tikar jamuan: Ngeduang menjamu tetamu sebagai sedekah, Kota Belud", "top": "78.5%", "left": "17.5%"}, {"name": "Rumah di atas air: perkampungan Bajau di pantai timur", "top": "25.4%", "left": "14.2%"}], "aftermath": "Petunjuk tidak ditemui dan pelancong pulang dengan maklumat yang salah.", "turns": [{"after": 6, "options": [{"text": "Kita boleh mempelajari budaya Bajau tanpa mengubah cara hidup mereka.", "isCorrect": true, "reaction": "Betul, nak."}, {"text": "Kita suruh mereka tukar upacara supaya senang difahami dan biarkan sahaja.", "isCorrect": false, "reaction": "Pak Bajau tersinggung dan upacara dihentikan."}, {"text": "Bagi aku, kita ambil gambar tanpa meminta izin, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Penduduk berasa tidak dihormati."}], "clue": "Pelajari dengan hormat dan izin."}]}'),
(516, 'e5_n2_s8', 'Para Penjaga Adat', 'Padankan penjaga adat dengan kaum atau upacaranya.', '4', 'Merumuskan tokoh upacara: Bobohizan (Kadazandusun), Lemambang (Iban), Mah Meri (Puja Pantai), Bisaya (Tamarok), Bajau (Ngeduang dan Mag''ombo).', '{"pairs": [{"text": "Bobohizan", "pair": 1}, {"text": "Ketua bomoh Kadazandusun, Magavau", "pair": 1}, {"text": "Lemambang", "pair": 2}, {"text": "Penyair upacara Miring Iban", "pair": 2}, {"text": "Suku Mah Meri", "pair": 3}, {"text": "Puja Pantai di Pulau Carey", "pair": 3}, {"text": "Masyarakat Bisaya", "pair": 4}, {"text": "Tamarok menghalau kuasa ghaib", "pair": 4}, {"text": "Masyarakat Bajau", "pair": 5}, {"text": "Ngeduang dan Mag''ombo", "pair": 5}], "aftermath": "Padanan tersilap dan persidangan berakhir dengan kekeliruan tentang siapa menjaga apa.", "turns": [{"after": 7, "options": [{"text": "Menurut aku, kepercayaan setiap kaum perlu difahami dan dihormati agar kehidupan aman.", "isCorrect": true, "reaction": "Itu jawapan yang membawa kami pulang dengan tenang."}, {"text": "Kepercayaan kaum lain tidak perlu difahami, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Wakil-wakil lain terasa tidak dihargai."}, {"text": "Aku fikir hanya satu kepercayaan yang betul, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Persidangan menjadi tegang dan wakil meninggalkan dewan."}], "clue": "Fahami dan hormati semua kepercayaan."}]}'),
(517, 'e5_n3_s1', 'Kad Kedudukan Agama Islam', 'Susun peristiwa kedudukan agama Islam dalam Perlembagaan mengikut urutan.', '1', 'Memahami proses: memorandum kepada Suruhanjaya Perlembagaan Tanah Melayu 1957, Islam diakui agama Persekutuan, termaktub dalam Perkara 3, perubahan perlu titah perkenan.', '{"timelineItems": [{"id": 1, "year": "Menjelang 1957", "text": "Parti politik dan pertubuhan menghantar memorandum kepada Suruhanjaya Perlembagaan Tanah Melayu 1957", "why": "Permulaan: cadangan dihantar kepada suruhanjaya."}, {"id": 2, "year": "Selepas itu", "text": "Agama Islam diakui sebagai agama Persekutuan", "why": "Memorandum diterima dan kedudukan itu diakui."}, {"id": 3, "year": "Kemudian", "text": "Kedudukannya termaktub dalam Perkara 3 Perlembagaan Persekutuan", "why": "Pengakuan itu ditulis dalam Perlembagaan."}, {"id": 4, "year": "Kini", "text": "Perubahan perlu mendapat titah perkenan Yang di-Pertuan Agong dan Raja-Raja Melayu", "why": "Syarat ini menjaga kedudukan itu daripada diubah sewenang-wenangnya."}], "aftermath": "Urutan terbalik dan murid mencatat sejarah yang salah. Guru menggeleng kecewa.", "turns": [{"after": 6, "options": [{"text": "Kedudukan itu termaktub dalam Perlembagaan dan wajar dihormati.", "isCorrect": true, "reaction": "Betul, nak. Itu menjaga perpaduan."}, {"text": "Bagi aku, kedudukan itu boleh diubah oleh sesiapa sahaja.", "isCorrect": false, "reaction": "Perubahan perlu titah perkenan. Guru membetulkan."}, {"text": "Rasanya, kedudukan itu tidak tercatat di mana-mana.", "isCorrect": false, "reaction": "Guru menggeleng. Ia termaktub dalam Perkara 3."}], "clue": "Perkara 3 menjaga kedudukan Islam."}]}'),
(518, 'e5_n3_s2', 'Papan Perkara 3', 'Padankan peruntukan Perkara 3 dengan isinya.', '4', 'Memahami Perkara 3 (1), (2), (3) dan (5) Perlembagaan Persekutuan.', '{"pairs": [{"text": "Perkara 3 (1)", "pair": 1}, {"text": "Islam agama Persekutuan, agama lain diamalkan dengan aman dan damai", "pair": 1}, {"text": "Perkara 3 (2)", "pair": 2}, {"text": "Raja ialah Ketua Agama Islam di negeri berRaja", "pair": 2}, {"text": "Perkara 3 (3)", "pair": 3}, {"text": "Yang di-Pertuan Agong: Melaka, Pulau Pinang, Sabah, Sarawak", "pair": 3}, {"text": "Perkara 3 (5)", "pair": 4}, {"text": "Yang di-Pertuan Agong: Kuala Lumpur, Labuan dan Putrajaya", "pair": 4}], "aftermath": "Papan salah baca dan murid menyangka Perdana Menteri ialah Ketua Agama Islam. Tuanku Sultan menggeleng.", "turns": [{"after": 7, "options": [{"text": "Yang di-Pertuan Agong ialah Ketua Agama Islam bagi negeri yang tidak mempunyai Raja.", "isCorrect": true, "reaction": "Betul, nak."}, {"text": "Perdana Menteri ialah Ketua Agama Islam bagi negeri itu, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Tuanku Sultan menggeleng. Itu tidak tercatat dalam Perkara 3."}, {"text": "Tiada sesiapa menjadi Ketua Agama Islam bagi negeri itu, jadi tidak perlu bersusah payah.", "isCorrect": false, "reaction": "Yang di-Pertua Negeri berasa dipandang remeh."}], "clue": "Negeri tanpa Raja: Yang di-Pertuan Agong."}]}'),
(519, 'e5_n3_s3', 'Kad Perkara 11', 'Padankan fasal dalam Perkara 11 dengan isinya.', '4', 'Memahami Perkara 11 (1) dan Perkara 11 (3)(a) Perlembagaan Persekutuan tentang kebebasan beragama.', '{"pairs": [{"text": "Perkara 11 (1)", "pair": 1}, {"text": "Tiap-tiap orang berhak menganuti dan mengamalkan agamanya", "pair": 1}, {"text": "Perkara 11 (3)(a)", "pair": 2}, {"text": "Tiap-tiap kumpulan agama berhak menguruskan hal ehwal agamanya sendiri", "pair": 2}], "aftermath": "Fasal tersilap dan pemuda itu terus menyebarkan salah faham tentang kebebasan beragama.", "turns": [{"after": 6, "options": [{"text": "Sebenarnya, perlembagaan menjamin hak beragama, jadi kita menghormati amalan agama masing-masing.", "isCorrect": true, "reaction": "Itu yang kami mahu dengar."}, {"text": "Perlembagaan tidak menjamin hak beragama, kerana tiada siapa yang akan peduli dan biarkan sahaja.", "isCorrect": false, "reaction": "Kad Perkara 11 membuktikan sebaliknya. Pemuda itu dibetulkan."}, {"text": "Hanya satu agama berhak diamalkan, jadi tidak payah difikirkan panjang dan itu bukan urusan kita.", "isCorrect": false, "reaction": "Itu bertentangan dengan Perkara 3 (1) dan Perkara 11 (1)."}], "clue": "Hak beragama dijamin."}]}'),
(520, 'e5_n3_s4', 'Cari Rumah Ibadat di Pameran', 'Cari rumah ibadat untuk setiap agama dan ajaran.', '2', 'Mengenal pasti nama rumah ibadat: masjid, gereja, kuil, gurdwara, wat dan tokong.', '{"bgImage": "../assets/gameAsset/background/tempat_beribadat_semua.png", "hotspots": [{"name": "Masjid: rumah ibadat bagi penganut Islam", "top": "21.9%", "left": "14.7%"}, {"name": "Gereja: rumah ibadat bagi penganut Kristian", "top": "20.6%", "left": "40.1%"}, {"name": "Kuil: rumah ibadat bagi penganut Hindu", "top": "28.2%", "left": "53.2%"}, {"name": "Gurdwara: rumah ibadat bagi penganut Sikh", "top": "47%", "left": "12.9%"}, {"name": "Wat atau tokong: rumah ibadat bagi penganut Buddha", "top": "52.9%", "left": "51.2%"}, {"name": "Tokong: rumah ibadat bagi Ajaran Konfusius dan Ajaran Tao", "top": "65%", "left": "31%"}], "aftermath": "Pelancong masuk tanpa memahami adab dan penjaga rumah ibadat tersinggung.", "turns": [{"after": 7, "options": [{"text": "Menurut aku, setiap rumah ibadat mempunyai adab dan kita perlu mengetahuinya sebelum masuk.", "isCorrect": true, "reaction": "Betul. Penjaga pun tersenyum."}, {"text": "Kita masuk sahaja kerana semua rumah ibadat sama dan tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Penjaga rumah ibadat membantah kerana adab tidak diketahui."}, {"text": "Aku fikir kita tidak perlu masuk langsung, jadi cukup dibiarkan begitu sahaja dan lupakan sahaja.", "isCorrect": false, "reaction": "Pelancong terlepas peluang mengenali kepelbagaian agama dengan hormat."}], "clue": "Ketahui adab sebelum masuk."}]}'),
(521, 'e5_n3_s5', 'Tiga Masjid Bersejarah', 'Padankan masjid dengan maklumatnya.', '4', 'Memahami Masjid Negara (dirasmikan 27 Ogos 1965, 15 000 jemaah), Masjid Kampung Laut (abad ke-18, Kelantan), Masjid Al-Qadim (1830, Sibu).', '{"pairs": [{"text": "Masjid Negara", "pair": 1}, {"text": "Dirasmikan 27 Ogos 1965, boleh menampung 15 000 jemaah", "pair": 1}, {"text": "Masjid Kampung Laut", "pair": 2}, {"text": "Dibina abad ke-18, antara masjid tertua di Alam Melayu", "pair": 2}, {"text": "Masjid Al-Qadim", "pair": 3}, {"text": "Dibina 1830 di Sibu oleh Tuan Haji Salam Minangkabau", "pair": 3}], "aftermath": "Kad bertukar dan laporan memuatkan tahun yang salah. Guru memanggil pelajar semula.", "turns": [{"after": 6, "options": [{"text": "Bagi aku, masjid itu bukti sejarah dan perlu dijaga bersama.", "isCorrect": true, "reaction": "Betul. Kami akan menulis laporan dengan lengkap."}, {"text": "Masjid lama tidak perlu dijaga lagi, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Guru menggeleng kerana warisan boleh hilang."}, {"text": "Bagi aku, masjid lama hanya milik satu kaum, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Pelajar lain membantah kerana warisan itu milik negara."}], "clue": "Jaga bangunan bersejarah."}]}'),
(522, 'e5_n3_s6', 'Rumah Ibadat Bersejarah', 'Padankan rumah ibadat dengan keistimewaannya.', '4', 'Memahami keistimewaan: Gereja St. Michael (gereja granit tertua), Wat Boonyaram (wat Siam di Kodiang), Cheng Hoon Teng (Kediaman di Awan Hijau), Sri Rajakaliamman (kuil kaca), Wadda Gurdwara Sahib (seni bina Moor).', '{"pairs": [{"text": "Gereja St. Michael", "pair": 1}, {"text": "Gereja granit tertua di Malaysia, Sandakan, 1893", "pair": 1}, {"text": "Wat Boonyaram", "pair": 2}, {"text": "Wat Siam Buddha di Kodiang, Kedah, 1932", "pair": 2}, {"text": "Tokong Cheng Hoon Teng", "pair": 3}, {"text": "Kediaman di Awan Hijau, Melaka, 1645", "pair": 3}, {"text": "Kuil Sri Rajakaliamman", "pair": 4}, {"text": "Kuil kaca pertama dan satu-satunya di Malaysia", "pair": 4}, {"text": "Wadda Gurdwara Sahib", "pair": 5}, {"text": "Seni bina Moor dan moden, tapak warisan di Pulau Pinang", "pair": 5}], "aftermath": "Keistimewaan tersilap dan pameran memuatkan fakta yang salah. Pengunjung keliru.", "turns": [{"after": 7, "options": [{"text": "Rumah ibadat bersejarah menunjukkan kepelbagaian agama dan warisan negara.", "isCorrect": true, "reaction": "Betul. Pengunjung kagum."}, {"text": "Rumah ibadat tidak mempunyai nilai sejarah, jadi orang lain tidak perlu tahu.", "isCorrect": false, "reaction": "Rakan-rakan membantah kerana sejarahnya jelas."}, {"text": "Aku fikir hanya rumah ibadat besar yang bernilai, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Rakan-rakan tidak bersetuju kerana semuanya warisan."}], "clue": "Rumah ibadat ialah warisan negara."}]}'),
(523, 'e5_n3_s7', 'Kad Adab Rumah Ibadat', 'Baca kad dan tentukan kepentingan memahami adab ketika berada di rumah ibadat.', '5', 'Memahami kepentingan adab: menghormati kebebasan beragama, mengeratkan silaturahim dan perpaduan, mengenali agama lain, menunjukkan keperibadian terpuji.', '{"clueText": "Kad: Memahami adab dapat menghormati kebebasan beragama kaum lain yang termaktub dalam Perlembagaan Persekutuan, mengeratkan hubungan silaturahim dan perpaduan, mengenali agama lain, dan menunjukkan sifat keperibadian yang terpuji.", "options": [{"text": "Menghormati kebebasan beragama dan mengeratkan perpaduan.", "isCorrect": true}, {"text": "Menyisihkan agama lain supaya tidak berbalah.", "isCorrect": false, "consequence": "Penyisihan menambah curiga. Kad dikembalikan."}, {"text": "Mengelak daripada masuk ke rumah ibadat lain.", "isCorrect": false, "consequence": "Kad menyatakan sebaliknya: kita perlu mengenali agama lain."}, {"text": "Menjadikan semua rumah ibadat sama.", "isCorrect": false, "consequence": "Kad tidak menyatakan begitu. Setiap agama ada rumah ibadat tersendiri."}], "aftermath": "Kad tersalah baca dan murid memasuki rumah ibadat tanpa adab. Penjaga menegur dan lawatan terhenti.", "turns": [{"after": 7, "options": [{"text": "Kita menjaga adab kerana menghormati kebebasan beragama dan mengeratkan perpaduan.", "isCorrect": true, "reaction": "Betul, nak. Kamu sudah bersedia."}, {"text": "Kita menjaga adab hanya jika diperhati guru, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Murid lain mula tidak menghormati bila guru berpaling."}, {"text": "Menurut aku, kita tidak perlu menjaga adab kerana itu bukan agama kita.", "isCorrect": false, "reaction": "Penjaga rumah ibadat kecewa dan lawatan dibatalkan."}], "clue": "Adab menunjukkan hormat."}]}'),
(524, 'e5_n3_s8', 'Rumusan Hormat Kepelbagaian Agama', 'Padankan perkara dengan kepentingannya.', '4', 'Memahami kepentingan menghormati kepelbagaian agama: persefahaman, sensitiviti, silaturahim, harmoni, mengelak perbalahan.', '{"pairs": [{"text": "Menghormati agama lain", "pair": 1}, {"text": "Mengukuhkan rasa persefahaman dalam masyarakat", "pair": 1}, {"text": "Menjaga sensitiviti", "pair": 2}, {"text": "Mendidik diri menghormati pelbagai kaum", "pair": 2}, {"text": "Mengeratkan silaturahim", "pair": 3}, {"text": "Hubungan baik antara kaum", "pair": 3}, {"text": "Hidup dalam harmoni", "pair": 4}, {"text": "Setiap masyarakat aman dan sejahtera", "pair": 4}, {"text": "Mengelakkan perbalahan", "pair": 5}, {"text": "Tiada pergaduhan antara kaum", "pair": 5}], "aftermath": "Rumusan tersilap dan murid pulang tanpa memahami kepentingan menghormati kepelbagaian agama.", "turns": [{"after": 7, "options": [{"text": "Hormat kepada kepelbagaian agama mewujudkan persefahaman dan perpaduan.", "isCorrect": true, "reaction": "Betul, nak. Itulah yang kita mahu."}, {"text": "Sebenarnya, hormat tidak penting kerana agama masing-masing dan biarkan sahaja.", "isCorrect": false, "reaction": "Rakan-rakan menggeleng kerana sikap itu menjauhkan mereka."}, {"text": "Hormat hanya untuk agama sendiri, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Rakan-rakan lain terasa tersisih."}], "clue": "Hormat kepelbagaian membawa perpaduan."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e5_n1_s1', 'hint', 'Guru Nanak bersama Sikh, Siddharta Gautama bersama Buddha. Lao Tzu bersama Tao.', NULL, NULL),
(501, NULL, 'hint', 'Islam menyembah Allah Yang Maha Esa. Buddha, Sikh, Konfusius dan Tao masing-masing ada pengasasnya.', 'Di meja pertama Pameran Tujuh Pintu aku membetulkan kad pengasas. Islam menyembah Allah Yang Maha Esa, Kristian dibawa oleh Jesus Christ, Buddha diasaskan oleh Siddharta Gautama, Sikh oleh Guru Nanak, Konfusius oleh Kung Fu Tze dan Tao oleh Lao Tzu.', 'Tepat! Aishah, Daniel, Mei Ling, Harjit dan Kenny masing-masing menerima semula kad mereka dengan senyuman lega.'),
(NULL, 'e5_n1_s2', 'hint', 'Tipitaka bagi Buddha, Bible bagi Kristian, Tao Te Ching bagi ajaran Tao.', NULL, NULL),
(502, NULL, 'hint', 'Al-Quran bersama Hadis ialah Islam. Veda bersama Hindu. Sri Guru Granth Sahib bersama Sikh.', 'Rak kitab suci hampir bercampur aduk. Aku susun semula, al-Quran dan Hadis untuk Islam, Bible untuk Kristian, Tipitaka untuk Buddha, Veda untuk Hindu, Sri Guru Granth Sahib untuk Sikh dan Tao Te Ching untuk ajaran Tao.', 'Kemas! Setiap kitab kembali ke tempatnya dan Daniel menarik nafas lega apabila Bible diletakkan dengan hormat.'),
(NULL, 'e5_n1_s3', 'hint', 'Kad itu mengaitkan kelakuan semasa hidup dengan kelahiran semula selepas mati.', NULL, NULL),
(503, NULL, 'hint', 'Kavitha menyebut Veda, dan Hukum Karma yang berkait dengan kelakuan semasa hidup.', 'Kavitha menerangkan kepada kami bahawa agama Hindu mempercayai Hukum Karma. Kelakuan seseorang semasa hidup berkait dengan kelahiran semula selepas mati, dan kitab sucinya ialah Veda.', 'Betul! Kavitha tersenyum lega kerana akhirnya kawan-kawannya mendengar, bukan mengejek.'),
(NULL, 'e5_n1_s4', 'hint', 'Kad itu menyebut Analek. Prinsip moralnya ialah perikemanusiaan, kesusilaan dan ketaatan.', NULL, NULL),
(504, NULL, 'hint', 'Kenny menyebut buku Analek, Kung Fu Tze, dan tiga prinsip moral termasuk ketaatan kepada ibu bapa.', 'Kenny mengajarku beza antara dua ajaran. Ajaran Konfusius diasaskan oleh Kung Fu Tze dan terkandung dalam buku Analek, menekankan perikemanusiaan, kesusilaan dan ketaatan kepada ibu bapa, manakala ajaran Tao ialah jalan hidup.', 'Hebat! Kenny mengangguk bangga, dan pengunjung itu mula faham bahawa dua ajaran itu tidak sama.'),
(NULL, 'e5_n1_s5', 'hint', 'Cara penyebarannya bukan satu. Ia melibatkan pemerintah, pedagang dan golongan agama.', NULL, NULL),
(505, NULL, 'hint', 'Tiga pihak menyebarkan agama. Pemerintah, pedagang dan satu lagi pihak yang mengajar ajaran agama.', 'Aku mencatat bahawa agama tersebar di Malaysia dengan pelbagai cara. Peranan pemerintah, pedagang dan golongan agama semuanya membawa ajaran ke negara ini.', 'Tepat sekali! Murid itu menulis tiga pihak itu dalam bukunya sambil mengangguk-angguk.'),
(NULL, 'e5_n1_s6', 'hint', 'Ahad di gereja bagi Kristian. Tao bermaksud jalan, hidup harmoni dengan alam.', NULL, NULL),
(506, NULL, 'hint', 'Waheguru bersama Sikh. Rukun Islam dan Rukun Iman bersama Islam. Empat Kebenaran Mulia bersama Buddha.', 'Aku belajar amalan yang berbeza. Islam ada Rukun Islam dan Rukun Iman, Kristian mengkhaskan hari Ahad di gereja, Sikh percaya Waheguru, Buddha berpegang kepada Empat Kebenaran Mulia dan Jalan Lapan Lapis Mulia, dan ajaran Tao mementingkan hidup harmoni dengan alam.', 'Betul! Lima kawan itu bertepuk tangan kerana amalan mereka difahami dan disebut dengan yakin.'),
(NULL, 'e5_n1_s7', 'hint', 'Kuil bagi Hindu dan gurdwara bagi Sikh. Tokong dan wat dikaitkan dengan Buddha.', NULL, NULL),
(507, NULL, 'hint', 'Masjid, gereja, kuil, gurdwara, wat atau tokong, dan tokong. Cari satu bagi setiap agama.', 'Aku mencari enam rumah ibadat di peta. Masjid untuk Islam, gereja untuk Kristian, kuil untuk Hindu, gurdwara untuk Sikh, wat atau tokong untuk Buddha, dan tokong untuk ajaran Konfusius dan Tao.', 'Cekap! Bas pelancong bergerak perlahan sementara mereka membaca nama setiap rumah ibadat pada papan yang kau tunjuk.'),
(NULL, 'e5_n1_s8', 'hint', 'Amalan agama menjadikan masyarakat maju dan harmoni. Disiplin dan matlamat menyusul.', NULL, NULL),
(508, NULL, 'hint', 'Kad itu menyebut empat kesan. Maju, harmoni, berdisiplin dan bermatlamat.', 'Pameran Tujuh Pintu ditutup dengan satu pengajaran. Amalan agama dan kepercayaan menjadikan masyarakat maju, hidup harmoni, berdisiplin dan mempunyai matlamat dalam kehidupan.', 'Tahniah! Pengkaji Budaya menutup buku nota lapangan itu dan menyerahkannya kepadamu sebagai tanda kepercayaan.'),
(NULL, 'e5_n2_s1', 'hint', 'Animisme. Gua, pokok atau batu besar dianggap mempunyai semangat.', NULL, NULL),
(509, NULL, 'hint', 'Alam semesta mempunyai semangat dan roh nenek moyang. Nama kepercayaan itu bermula dengan huruf A.', 'Di persidangan para penjaga adat aku belajar tentang animisme, iaitu kepercayaan bahawa alam semesta mempunyai semangat. Gua, pokok atau batu besar dihormati kerana ada roh nenek moyang di dalamnya.', 'Tepat! Bobohizan mengangguk perlahan, dan penduduk kampung bertepuk lembut sebagai tanda setuju.'),
(NULL, 'e5_n2_s2', 'hint', 'Puja Pantai berlaku di tepi laut untuk memohon perlindungan dan pengampunan.', NULL, NULL),
(510, NULL, 'hint', 'Mah Meri dengan Puja Pantai. Temiar dan Semai menghalau kuasa jahat. Orang Asli percaya penyakit datang daripada kuasa jahat.', 'Aku mendengar dua suku Orang Asli bercerita. Suku Mah Meri mengadakan Puja Pantai untuk memohon perlindungan dan pengampunan daripada semangat laut, manakala Temiar dan Semai mengadakan upacara ritual untuk menghalau kuasa jahat kerana mereka percaya penyakit disebabkan kuasa jahat.', 'Bagus! Tok Batin tersenyum dan Pak Mah Meri menepuk bahumu dengan mesra.'),
(NULL, 'e5_n2_s3', 'hint', 'Jampi mantera dibaca di permulaan upacara Miring.', NULL, NULL),
(511, NULL, 'hint', 'Petara menyampaikan petanda melalui mimpi dan bayangan. Lemambang pula penyair yang melakukan Miring.', 'Apai Jelani dan Lemambang mengajarku istilah Iban. Petara ialah dewa yang menyampaikan petanda melalui mimpi dan bayangan, Miring ialah upacara memuja Petara, Lemambang ialah penyair yang melakukan Miring, dan jampi mantera dibaca pada permulaannya.', 'Tepat! Lemambang tersenyum bangga kerana kau menyebut istilah leluhurnya dengan betul.'),
(NULL, 'e5_n2_s4', 'hint', 'Nama upacara itu Tamarok.', NULL, NULL),
(512, NULL, 'hint', 'Pak Tani Bisaya menyebut satu nama upacara bermula dengan T untuk menghalau kuasa ghaib daripada pesakit.', 'Pak Tani Bisaya menceritakan kisah masyarakatnya. Mereka petani yang mempercayai kuasa ghaib, membaca jampi mantera ketika membuka tanah baharu, dan mengadakan upacara Tamarok untuk menghalau kuasa ghaib daripada badan pesakit.', 'Tepat sekali! Pak Tani menepuk tangan dan pesakit di sudut dewan tersenyum tenang.'),
(NULL, 'e5_n2_s5', 'hint', 'Ngeduang bermakna menjamu tetamu sebagai sedekah. Mag''ombo bermakna menghormati warisan nenek moyang.', NULL, NULL),
(513, NULL, 'hint', 'Kota Belud ialah pantai barat Sabah, tempat Ngeduang. Semporna di pantai timur, tempat Mag''ombo.', 'Pak Bajau mengajarku dua upacara. Ngeduang diadakan di Kota Belud di pantai barat Sabah, apabila keluarga si mati menjamu tetamu sebagai sedekah, manakala Mag''ombo di Semporna di pantai timur menghargai dan menghormati warisan nenek moyang.', 'Bagus! Pak Bajau tersenyum lebar kerana kau menyebut nama kedua-dua upacara dengan betul.'),
(NULL, 'e5_n2_s6', 'hint', 'Bukan nama kampung. Kinorohingan ialah Tuhan untuk meminta keselamatan dan perlindungan.', NULL, NULL),
(514, NULL, 'hint', 'Kinorohingan ialah Tuhan. Magavau dilakukan semasa Pesta Kaamatan. Ketua bomoh ialah Bobohizan.', 'Linda dan Bobohizan menerangkan istilah Kadazandusun. Kinorohingan ialah Tuhan untuk meminta keselamatan dan perlindungan, Magavau ialah upacara semangat padi semasa Pesta Kaamatan, dan Bobohizan ialah ketua bomoh yang mengetuai upacara itu.', 'Hebat! Linda tersenyum, dan bunyi sompoton kedengaran perlahan di luar dewan.'),
(NULL, 'e5_n2_s7', 'hint', 'Tikar jamuan berkait dengan Ngeduang. Perahu berhias dan gerbang berkait dengan Mag''ombo.', NULL, NULL),
(515, NULL, 'hint', 'Empat petunjuk. Perahu berhias, gerbang upacara, tikar jamuan dan rumah di atas air.', 'Di perkampungan atas air aku mencari empat petunjuk. Perahu berhias dan gerbang upacara menandakan Mag''ombo di Semporna, tikar jamuan menandakan Ngeduang di Kota Belud, dan rumah di atas air ialah perkampungan Bajau di pantai timur.', 'Mata yang tajam! Pak Bajau menepuk bahumu kerana keempat-empat petunjuk dijumpai tanpa mengganggu upacara.'),
(NULL, 'e5_n2_s8', 'hint', 'Pulau Carey ialah tempat Puja Pantai suku Mah Meri.', NULL, NULL),
(516, NULL, 'hint', 'Bobohizan dengan Magavau, Lemambang dengan Miring, Mah Meri dengan Puja Pantai di Pulau Carey. Bisaya dengan Tamarok, Bajau dengan Ngeduang dan Mag''ombo.', 'Persidangan para penjaga adat berakhir dengan kepercayaan yang jelas bagiku. Bobohizan mengetuai Magavau, Lemambang melakukan Miring, Mah Meri mengadakan Puja Pantai di Pulau Carey, Bisaya mengadakan Tamarok, dan Bajau mengadakan Ngeduang serta Mag''ombo.', 'Tahniah! Para penjaga adat berdiri satu demi satu dan menunduk hormat kepadamu.'),
(NULL, 'e5_n3_s1', 'hint', 'Selepas memorandum, Islam diakui sebagai agama Persekutuan, lalu termaktub dalam Perkara 3.', NULL, NULL),
(517, NULL, 'hint', 'Mulakan dengan memorandum menjelang 1957. Penutupnya titah perkenan Yang di-Pertuan Agong dan Raja-Raja Melayu.', 'Aku menyusun urutan kedudukan agama Islam dalam Perlembagaan. Menjelang 1957, memorandum dihantar kepada Suruhanjaya Perlembagaan, kemudian Islam diakui sebagai agama Persekutuan, termaktub dalam Perkara 3, dan kini perubahan perlu titah perkenan Yang di-Pertuan Agong dan Raja-Raja Melayu.', 'Tepat! Cikgu mengangguk puas dan murid-murid menulis urutan itu dalam buku mereka.'),
(NULL, 'e5_n3_s2', 'hint', 'Perkara 3 (3) untuk Melaka, Pulau Pinang, Sabah dan Sarawak. Perkara 3 (5) untuk Kuala Lumpur, Labuan dan Putrajaya.', NULL, NULL),
(518, NULL, 'hint', 'Raja ialah Ketua Agama di negeri berRaja. Yang di-Pertuan Agong memegang peranan itu bagi negeri tanpa Raja dan wilayah persekutuan.', 'Tuanku Sultan dan Yang di-Pertua Negeri mengajarku Perkara 3. Islam ialah agama Persekutuan, Raja menjadi Ketua Agama Islam di negeri berRaja, manakala Yang di-Pertuan Agong menjadi Ketua Agama Islam di Melaka, Pulau Pinang, Sabah, Sarawak, Kuala Lumpur, Labuan dan Putrajaya.', 'Tepat! Tuanku Sultan tersenyum dan Yang di-Pertua Negeri mengangguk menandakan setuju.'),
(NULL, 'e5_n3_s3', 'hint', 'Satu fasal bagi individu, satu fasal bagi kumpulan agama.', NULL, NULL),
(519, NULL, 'hint', 'Perkara 11 (1) tentang hak menganuti agama. Perkara 11 (3)(a) tentang kumpulan agama menguruskan hal ehwalnya sendiri.', 'Aku membaca Perkara 11 bersama kawan-kawan. Perkara 11 (1) menjamin hak setiap orang menganuti dan mengamalkan agamanya, dan Perkara 11 (3)(a) menjamin hak tiap-tiap kumpulan agama menguruskan hal ehwal agamanya sendiri.', 'Tepat! Harjit mengangkat kad Perkara 11 itu tinggi-tinggi sambil tersenyum.'),
(NULL, 'e5_n3_s4', 'hint', 'Gurdwara bagi Sikh, kuil bagi Hindu. Tokong juga dikaitkan dengan Konfusius dan Tao.', NULL, NULL),
(520, NULL, 'hint', 'Masjid, gereja, kuil, gurdwara, wat atau tokong, dan tokong. Enam rumah ibadat, enam agama atau ajaran.', 'Di pameran aku mencari enam rumah ibadat. Masjid untuk Islam, gereja untuk Kristian, kuil untuk Hindu, gurdwara untuk Sikh, wat atau tokong untuk Buddha, dan tokong untuk ajaran Konfusius dan Tao.', 'Cekap! Penjaga setiap rumah ibadat tersenyum kerana kau menyebut nama mereka dengan betul.'),
(NULL, 'e5_n3_s5', 'hint', 'Tuan Haji Salam Minangkabau membina masjid di Sibu pada 1830.', NULL, NULL),
(521, NULL, 'hint', 'Masjid Negara 27 Ogos 1965. Kampung Laut abad ke-18. Al-Qadim 1830 di Sibu.', 'Aishah memperkenalkan tiga masjid bersejarah. Masjid Negara dirasmikan pada 27 Ogos 1965 dan boleh menampung 15 000 jemaah, Masjid Kampung Laut dibina pada abad ke-18, dan Masjid Al-Qadim dibina pada 1830 di Sibu oleh Tuan Haji Salam Minangkabau.', 'Tepat! Aishah tersenyum, dan murid lain menulis tarikh itu dalam buku masing-masing.'),
(NULL, 'e5_n3_s6', 'hint', 'Tokong Cheng Hoon Teng di Melaka dahulu sebuah kediaman. Wadda Gurdwara Sahib di Pulau Pinang bergaya Moor dan moden.', NULL, NULL),
(522, NULL, 'hint', 'Gereja granit di Sandakan. Wat Siam di Kodiang. Kuil kaca ialah Sri Rajakaliamman.', 'Kawan-kawan membawaku melawat rumah ibadat bersejarah. Gereja St. Michael di Sandakan ialah gereja granit tertua, Wat Boonyaram di Kodiang wat Siam Buddha, Tokong Cheng Hoon Teng di Melaka asalnya kediaman, Kuil Sri Rajakaliamman kuil kaca satu-satunya, dan Wadda Gurdwara Sahib di Pulau Pinang tapak warisan.', 'Hebat! Setiap kawan tersenyum bangga apabila rumah ibadat mereka disebut dengan betul.'),
(NULL, 'e5_n3_s7', 'hint', 'Adab menghormati kebebasan beragama. Ia juga mengeratkan silaturahim dan perpaduan.', NULL, NULL),
(523, NULL, 'hint', 'Kad itu menyebut kebebasan beragama dalam Perlembagaan dan perpaduan yang bertambah erat.', 'Aku belajar bahawa memahami adab di rumah ibadat menghormati kebebasan beragama kaum lain yang termaktub dalam Perlembagaan Persekutuan. Ia juga mengeratkan silaturahim dan perpaduan, membantu kita mengenali agama lain, dan menunjukkan keperibadian terpuji.', 'Betul, nak! Lemambang menutup syairnya sebentar, dan seluruh dewan mengangguk bersama.'),
(NULL, 'e5_n3_s8', 'hint', 'Silaturahim bermaksud hubungan baik antara kaum. Elak perbalahan bermaksud tiada pergaduhan.', NULL, NULL),
(524, NULL, 'hint', 'Lima rumusan, iaitu hormat agama lain, jaga sensitiviti, eratkan silaturahim, hidup harmoni, elak perbalahan.', 'Syair terakhir Lemambang merumuskan semuanya. Menghormati agama lain mengukuhkan persefahaman, menjaga sensitiviti mendidik kita menghormati pelbagai kaum, silaturahim mengeratkan hubungan antara kaum, hidup harmoni menjadikan masyarakat aman, dan mengelakkan perbalahan bermakna tiada pergaduhan.', 'Tahniah! Pesta Kepercayaan ditutup dengan tepukan gemuruh dan semua kaum berdiri bersama.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(81, 501, NULL, 'Tugasku ialah mencatat agama dan kepercayaan dengan adil dan hormat. Satu catatan yang salah boleh menyinggung hati sebuah masyarakat, {nama}.', 1),
(81, 501, NULL, 'Aku belajar bahawa setiap agama menuntut penganutnya melakukan perkara baik. Menghormati agama kaum lain menjamin kehidupan aman dan sejahtera.', 2),
(81, 501, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengkaji yang membawa buku nota lapangan. Catat dengan teliti dan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(81, 501, 'e5_n1_s1', 'Selamat datang ke Pameran Tujuh Pintu. Ini buku nota lapangan engkau. Namun lihat meja pertama itu, kad pengasas agama telah bertukar-tukar tempat dek budak-budak berlari tadi.', 1),
(84, 501, 'e5_n1_s1', 'Kami penganut Islam hanya menyembah Allah Yang Maha Esa. Kad kami tiada nama pengasas lain di atasnya.', 2),
(85, 501, 'e5_n1_s1', 'Agama Kristian dibawa oleh Jesus Christ. Ada yang tersilap letak nama lain pada kad saya.', 3),
(86, 501, 'e5_n1_s1', 'Agama Buddha diasaskan oleh Siddharta Gautama. Tadi kad saya dilekatkan nama Guru Nanak pula!', 4),
(88, 501, 'e5_n1_s1', 'Guru Nanak itu pengasas agama Sikh, jadi kad itu milik kami. Kenny, ajaran engkau pun terbalik juga, bukan?', 5),
(89, 501, 'e5_n1_s1', 'Benar. Ajaran Konfusius diasaskan oleh Kung Fu Tze, dan ajaran Tao diasaskan oleh Lao Tzu.', 6),
(81, 501, 'e5_n1_s1', 'Lengkaplah telah. Kini tolong padankan setiap agama dengan pengasasnya sebelum pengunjung tiba. Namun kenapa kita perlu berhati-hati ketika mencatat nota tentang agama orang lain?', 7),
(85, 501, 'e5_n1_s2', 'Cikgu pengkaji, rak kitab suci ini kacau-bilau. Bible saya terselit di sebelah al-Quran tanpa label.', 1),
(84, 501, 'e5_n1_s2', 'Kitab kami ialah al-Quran, dan ajaran kami juga berpandukan Hadis. Tolong letakkan dengan penuh hormat.', 2),
(87, 501, 'e5_n1_s2', 'Veda ialah kitab suci agama Hindu. Usah disorok di bawah buku lain.', 3),
(86, 501, 'e5_n1_s2', 'Agama Buddha pula berpandukan kitab Tipitaka.', 4),
(88, 501, 'e5_n1_s2', 'Sri Guru Granth Sahib ialah kitab suci agama Sikh. Kami menyimpannya di tempat yang tinggi dan bersih.', 5),
(89, 501, 'e5_n1_s2', 'Dan Tao Te Ching ialah buku ajaran Tao. Usah terbalik dengan Analek yang milik ajaran Konfusius.', 6),
(81, 501, 'e5_n1_s2', 'Nampaknya kerja engkau telah jelas. Padankan semua kitab dengan agamanya. Namun apa maknanya jikalau kita meletakkan kitab suci orang lain sesuka hati?', 7),
(98, 501, 'e5_n1_s3', 'Cikgu, kawan-kawan ketawa apabila Kavitha berkata dia percaya kelahiran semula. Saya tidak faham bahagian itu.', 1),
(87, 501, 'e5_n1_s3', 'Aku bukan hendak bergurau. Dalam kitab Veda kami, ada Hukum Karma yang berkait dengan kelakuan manusia semasa hidup.', 2),
(87, 501, 'e5_n1_s3', 'Perbuatan baik atau buruk di dunia ini akan menentukan kelahiran semula selepas mati. Itulah yang kami yakini.', 3),
(NULL, 501, 'e5_n1_s3', 'Kad ini pun tertulis begitu. Penganut agama Hindu mempercayai Hukum Karma dan kelahiran semula selepas mati.', 4),
(98, 501, 'e5_n1_s3', 'Oh, jadi itu bukan sebuah dongeng. Namun jikalau begitu, bagaimanakah kami patut bersikap terhadap kepercayaan Kavitha?', 5),
(89, 501, 'e5_n1_s4', 'Pengunjung tadi menyangka ajaran Konfusius dan ajaran Tao itu sama. Saya cuba menerangkan namun mereka tidak percaya.', 1),
(86, 501, 'e5_n1_s4', 'Aku ada dengar, Konfusius mementingkan moral dalam sebuah buku. Apa nama buku itu, Kenny?', 2),
(89, 501, 'e5_n1_s4', 'Analek. Ajaran Konfusius diasaskan oleh Kung Fu Tze dan menekankan prinsip moral yang tinggi, seperti perikemanusiaan dan kesusilaan.', 3),
(89, 501, 'e5_n1_s4', 'Anak-anak juga diajar taat kepada ibu bapa. Itu bukan ajaran Tao, kerana Tao bermaksud jalan.', 4),
(NULL, 501, 'e5_n1_s4', 'Kad ini pun menyebut perkara yang sama, Kenny. Aku akan membacanya kepada pengunjung dengan hormat.', 5),
(89, 501, 'e5_n1_s4', 'Terima kasih. Tolong cakap pada mereka, ajaran ini mementingkan perikemanusiaan, kesusilaan dan ketaatan kepada ibu bapa. Lalu bagaimanakah jikalau ada yang masih berkata kedua-dua ajaran itu sama?', 6),
(98, 501, 'e5_n1_s5', 'Cikgu, mengapakah ada begitu banyak agama di Malaysia? Adakah semuanya dibawa orang luar sahaja?', 1),
(81, 501, 'e5_n1_s5', 'Soalan yang baik. Nota lapangan kita menyebut agama Islam, Kristian, Buddha, Hindu dan Sikh, serta ajaran Konfusius dan Tao. Semuanya tersebar dengan cara yang berbeza.', 2),
(84, 501, 'e5_n1_s5', 'Sebahagiannya tersebar melalui peranan pemerintah yang menerima sesuatu agama, lalu rakyatnya mengikut.', 3),
(86, 501, 'e5_n1_s5', 'Para pedagang yang berdagang dari negeri jauh juga membawa agama mereka bersama barang dagangan.', 4),
(87, 501, 'e5_n1_s5', 'Golongan agama pula menyebarkan ajaran, mengajar dan membina rumah ibadat di sini.', 5),
(NULL, 501, 'e5_n1_s5', 'Jadi cara penyebarannya melalui peranan pemerintah, pedagang dan golongan agama.', 6),
(98, 501, 'e5_n1_s5', 'Aku faham kini. Namun jikalau begitu, apa yang patut kita fikirkan tentang semua agama yang telah bertapak di sini?', 7),
(85, 501, 'e5_n1_s6', 'Setiap Ahad kami pergi ke gereja. Hari itu dikhaskan untuk aktiviti keagamaan kami.', 1),
(88, 501, 'e5_n1_s6', 'Maka kami penganut Sikh percaya kepada satu Tuhan bernama Waheguru.', 2),
(84, 501, 'e5_n1_s6', 'Agama Islam mempunyai dua teras, iaitu Rukun Islam dan Rukun Iman. Itulah asas amalan kami.', 3),
(86, 501, 'e5_n1_s6', 'Dalam agama Buddha, kami berpegang kepada Empat Kebenaran Mulia dan Jalan Lapan Lapis Mulia.', 4),
(89, 501, 'e5_n1_s6', 'Dan ajaran Tao pula menekankan bahawa Tao bermaksud jalan, iaitu hidup harmoni dengan alam.', 5),
(81, 501, 'e5_n1_s6', 'Cantik. Padankan kelima-lima amalan itu dengan agama atau ajarannya. Namun mengapakah kita perlu belajar amalan agama yang berbeza daripada kita?', 6),
(98, 501, 'e5_n1_s7', 'Cikgu, pelancong tadi memanggil semua rumah ibadat ''temple''. Betulkah semuanya sama?', 1),
(81, 501, 'e5_n1_s7', 'Tidak, nak. Penganut Islam beribadat di masjid, dan penganut Kristian di gereja.', 2),
(87, 501, 'e5_n1_s7', 'Kuil ialah rumah ibadat bagi penganut Hindu, manakala gurdwara ialah rumah ibadat bagi penganut Sikh.', 3),
(86, 501, 'e5_n1_s7', 'Penganut Buddha biasanya ke wat atau tokong. Tokong juga rumah ibadat bagi ajaran Konfusius dan Tao.', 4),
(NULL, 501, 'e5_n1_s7', 'Enam bangunan di peta ini semuanya milik agama yang berbeza. Aku mesti mencarinya.', 5),
(98, 501, 'e5_n1_s7', 'Segera, bas pelancong akan bergerak sebentar lagi! Bagaimanakah jikalau mereka masuk tanpa tahu nama rumah ibadat itu?', 6),
(88, 501, 'e5_n1_s8', 'Cikgu pengkaji, kita telah mengenal semua agama dan ajaran. Namun untuk apa kita beragama?', 1),
(85, 501, 'e5_n1_s8', 'Mama kata agama mengajar kita menjadi orang baik.', 2),
(89, 501, 'e5_n1_s8', 'Benar, namun apa kepentingannya kepada seluruh masyarakat?', 3),
(81, 501, 'e5_n1_s8', 'Kad refleksi ini menjawabnya. Amalan agama dan kepercayaan menjadikan masyarakat lebih maju dan hidup dalam suasana harmoni.', 4),
(81, 501, 'e5_n1_s8', 'Ia memastikan masyarakat sentiasa berdisiplin, dan memimpin masyarakat supaya mempunyai matlamat dalam kehidupan.', 5),
(NULL, 501, 'e5_n1_s8', 'Maju, harmoni, berdisiplin dan bermatlamat. Aku akan tulis begitu dalam laporan nota lapangan.', 6),
(88, 501, 'e5_n1_s8', 'Kami semua setuju. Jadi jikalau kita telah tahu kepentingannya, bagaimanakah kita patut menjawab pertanyaan itu pada para pengunjung?', 7),
(82, 502, NULL, 'Tugasku ialah mengingatkan semua orang bahawa kepercayaan setiap kaum perlu difahami dan dihormati, {nama}.', 1),
(82, 502, NULL, 'Aku belajar bahawa kepercayaan masyarakat dipengaruhi oleh alam semesta. Semua agama dan kepercayaan menuntut penganutnya melakukan perkara baik.', 2),
(82, 502, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, ketua bomoh Kadazandusun yang menjaga semangat padi. Dengar setiap wakil dengan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(98, 502, 'e5_n2_s1', 'Bobohizan, orang kampung kata gua, pokok dan batu besar itu ada roh. Adakah itu juga satu agama?', 1),
(82, 502, 'e5_n2_s1', 'Itu kepercayaan nenek moyang kami, nak. Mereka menghormati semangat di sekeliling kita.', 2),
(91, 502, 'e5_n2_s1', 'Di pulau kami, orang tua-tua berkata alam semesta hidup. Gua, pokok dan batu besar mempunyai semangat, malah roh nenek moyang yang mesti dihormati.', 3),
(NULL, 502, 'e5_n2_s1', 'Kad persidangan ini menyebut perkara sama. Kepercayaan itu dipengaruhi oleh alam semesta.', 4),
(82, 502, 'e5_n2_s1', 'Namanya animisme. Ingat nama itu baik-baik, kerana wakil-wakil lain akan bertanya. Namun apa yang patut kita lakukan terhadap kepercayaan yang berbeza daripada kita?', 5),
(91, 502, 'e5_n2_s2', 'Kami suku Mah Meri mengadakan Puja Pantai untuk memohon perlindungan dan pengampunan daripada semangat laut.', 1),
(90, 502, 'e5_n2_s2', 'Kami suku Temiar dan Semai pula mengadakan upacara ritual untuk menghalau kuasa jahat.', 2),
(90, 502, 'e5_n2_s2', 'Orang Asli percaya penyakit disebabkan oleh kuasa jahat. Sebab itu upacara itu penting bagi kami.', 3),
(98, 502, 'e5_n2_s2', 'Pakcik Tok Batin, kenapa upacara suku Mah Meri dan Temiar berbeza?', 4),
(82, 502, 'e5_n2_s2', 'Setiap suku ada pegangan dan alasannya sendiri, nak. Engkau yang pegang kad, padankan mereka dengan upacara dan tujuannya.', 5),
(NULL, 502, 'e5_n2_s2', 'Mah Meri dengan Puja Pantai, Temiar dan Semai dengan upacara halau kuasa jahat, dan kepercayaan Orang Asli tentang penyakit itu.', 6),
(90, 502, 'e5_n2_s2', 'Benar. Nah, selepas engkau mengetahuinya, bagaimanakah engkau akan melayan upacara yang berbeza daripada adatmu?', 7),
(92, 502, 'e5_n2_s3', 'Kami masyarakat Iban percaya Petara akan menyampaikan alamat dan petanda melalui mimpi dan bayangan.', 1),
(83, 502, 'e5_n2_s3', 'Dan untuk memuja Petara, kami mengadakan upacara Miring. Aku Lemambang, penyair yang melakukan upacara itu.', 2),
(83, 502, 'e5_n2_s3', 'Upacara Miring bermula dengan bacaan jampi mantera. Setelah itu barulah semua perkara lain dijalankan.', 3),
(98, 502, 'e5_n2_s3', 'Namun, Pakcik Lemambang, siapakah sebenarnya Petara itu? Adakah nama tempat?', 4),
(94, 502, 'e5_n2_s4', 'Masyarakat Bisaya di Sarawak bekerja sebagai petani. Kami percaya kuasa ghaib wujud di tanah.', 1),
(94, 502, 'e5_n2_s4', 'Sebelum membuka kawasan pertanian baharu, kami membaca jampi mantera agar tiada gangguan kuasa ghaib.', 2),
(98, 502, 'e5_n2_s4', 'Pakcik, bagaimanakah jikalau ada orang yang jatuh sakit akibat gangguan itu?', 3),
(94, 502, 'e5_n2_s4', 'Kami adakan upacara untuk menghalau kuasa ghaib daripada badan pesakit. Upacara itu bernama Tamarok.', 4),
(NULL, 502, 'e5_n2_s4', 'Nota ini pun menyebut perkara yang sama. Upacara Tamarok menghalau kuasa ghaib daripada badan pesakit.', 5),
(94, 502, 'e5_n2_s4', 'Benar, nak. Namun jika engkau ke kampung kami, bagaimanakah engkau akan menunjukkan rasa hormat kepada upacara ini?', 6),
(95, 502, 'e5_n2_s5', 'Kami masyarakat Bajau ada dua upacara besar. Di Kota Belud, pantai barat Sabah, kami mengadakan Ngeduang.', 1),
(95, 502, 'e5_n2_s5', 'Ketahuilah, dalam Ngeduang, keluarga si mati menjamu tetamu sebagai sedekah.', 2),
(98, 502, 'e5_n2_s5', 'Dan di Semporna pula, Pakcik?', 3),
(95, 502, 'e5_n2_s5', 'Di Semporna, pantai timur Sabah, kami mengadakan Mag''ombo. Upacara itu menghargai dan menghormati warisan nenek moyang kami.', 4),
(NULL, 502, 'e5_n2_s5', 'Jadi Ngeduang bersama Kota Belud, dan Mag''ombo bersama Semporna. Aku akan padankan semuanya di kad ini.', 5),
(95, 502, 'e5_n2_s5', 'Benar. Walaupun lokasinya berbeza, apakah yang sama pada kedua-dua upacara ini?', 6),
(93, 502, 'e5_n2_s6', 'Bobohizan, apakah sebenarnya Kinorohingan? Ada orang kata itu nama kampung.', 1),
(82, 502, 'e5_n2_s6', 'Bukan, Linda. Kinorohingan ialah Tuhan yang kami minta keselamatan dan perlindungan.', 2),
(98, 502, 'e5_n2_s6', 'Dan Magavau, Bobohizan?', 3),
(93, 502, 'e5_n2_s6', 'Magavau, atau Maga''au, ialah upacara semangat padi semasa Pesta Kaamatan. Ia diketuai oleh Bobohizan.', 4),
(82, 502, 'e5_n2_s6', 'Ya, Bobohizan itulah ketua bomoh yang mengetuai upacara.', 5),
(NULL, 502, 'e5_n2_s6', 'Jadi Kinorohingan ialah Tuhan, Magavau ialah upacara semangat padi, dan Bobohizan ialah ketua bomoh. Aku akan padankan semuanya.', 6),
(93, 502, 'e5_n2_s6', 'Benar. Namun mengapakah masyarakat kami memanggil nama Tuhan sebelum menuai padi?', 7),
(95, 502, 'e5_n2_s7', 'Upacara Mag''ombo dan Ngeduang berbeza lokasi, namun kedua-duanya warisan kami.', 1),
(98, 502, 'e5_n2_s7', 'Di mana kita boleh nampak tanda-tanda upacara itu di perkampungan atas air ini?', 2),
(95, 502, 'e5_n2_s7', 'Perahu berhias itu untuk Mag''ombo di Semporna, dan gerbang upacara menghargai warisan turun-temurun kami.', 3),
(95, 502, 'e5_n2_s7', 'Tikar jamuan di tepi rumah pula untuk Ngeduang, kerana keluarga menjamu tetamu sebagai sedekah di Kota Belud. Rumah di atas air itu ialah perkampungan Bajau di pantai timur.', 4),
(NULL, 502, 'e5_n2_s7', 'Perahu berhias dan gerbang upacara untuk Mag''ombo. Tikar jamuan untuk Ngeduang. Aku akan cari keempat-empatnya.', 5),
(95, 502, 'e5_n2_s7', 'Teliti ya, usah terlepas yang di tikar jamuan. Jika kita hendak belajar budaya Bajau, bagaimanakah caranya agar mereka tidak tersinggung?', 6),
(82, 502, 'e5_n2_s8', 'Aku Bobohizan, ketua bomoh Kadazandusun. Aku mengetuai Magavau semasa Pesta Kaamatan.', 1),
(83, 502, 'e5_n2_s8', 'Aku Lemambang, penyair upacara Miring masyarakat Iban.', 2),
(91, 502, 'e5_n2_s8', 'Maka kami suku Mah Meri melakukan Puja Pantai di Pulau Carey.', 3),
(94, 502, 'e5_n2_s8', 'Masyarakat Bisaya mengadakan Tamarok untuk menghalau kuasa ghaib.', 4),
(95, 502, 'e5_n2_s8', 'Dan masyarakat Bajau mengadakan Ngeduang dan Mag''ombo.', 5),
(NULL, 502, 'e5_n2_s8', 'Aku akan padankan setiap penjaga adat dengan kaum atau upacaranya, satu demi satu.', 6),
(82, 502, 'e5_n2_s8', 'Sebelum persidangan ditutup, apakah yang engkau hendak bawa pulang sebagai pelajaran daripada semua kepercayaan ini?', 7),
(83, 503, NULL, 'Tugasku ialah melagukan syair yang mengajak semua orang memahami hak beragama dan menghormati rumah ibadat, {nama}.', 1),
(83, 503, NULL, 'Aku belajar bahawa Perlembagaan Persekutuan menjamin agama lain boleh diamalkan dengan aman dan damai. Kita juga perlu menjaga adab di rumah ibadat.', 2),
(83, 503, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penyair upacara yang melagukan puji-pujian. Dengar syair dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(98, 503, 'e5_n3_s1', 'Cikgu, bagaimanakah agama Islam diakui sebagai agama Persekutuan? Adakah ia berlaku dalam satu hari?', 1),
(96, 503, 'e5_n3_s1', 'Tidak, nak. Menjelang 1957, parti politik dan pertubuhan menghantar memorandum kepada Suruhanjaya Perlembagaan Tanah Melayu 1957.', 2),
(83, 503, 'e5_n3_s1', 'Ketahuilah, selepas itu, agama Islam diakui sebagai agama Persekutuan. Kemudian kedudukannya termaktub dalam Perkara 3 Perlembagaan Persekutuan.', 3),
(96, 503, 'e5_n3_s1', 'Kini, apa-apa perubahan perlu mendapat titah perkenan Yang di-Pertuan Agong dan Raja-Raja Melayu.', 4),
(NULL, 503, 'e5_n3_s1', 'Memorandum, diakui sebagai agama Persekutuan, termaktub dalam Perkara 3, dan perubahan perlu titah perkenan. Aku akan susun kad ikut urutan itu.', 5),
(98, 503, 'e5_n3_s1', 'Jikalau salah, murid akan hafal sejarah yang salah! Jadi mengapakah kedudukan ini perlu dihormati oleh semua orang?', 6),
(96, 503, 'e5_n3_s2', 'Beta ialah Ketua Agama Islam di negeri beta, kerana negeri ini mempunyai Raja. Itulah isi Perkara 3 (2).', 1),
(97, 503, 'e5_n3_s2', 'Negeriku tiada Raja, sebagaimana Melaka, Pulau Pinang, Sabah dan Sarawak. Menurut Perkara 3 (3), Yang di-Pertuan Agong menjadi Ketua Agama Islam di sini.', 2),
(98, 503, 'e5_n3_s2', 'Cikgu, bagaimanakah dengan Kuala Lumpur, Labuan dan Putrajaya?', 3),
(83, 503, 'e5_n3_s2', 'Perkara 3 (5) menyatakan bahawa Yang di-Pertuan Agong juga menjadi Ketua Agama Islam bagi ketiga-tiga wilayah itu.', 4),
(96, 503, 'e5_n3_s2', 'Perkara 3 (1) pula menyatakan agama Islam ialah agama Persekutuan, namun agama lain boleh diamalkan dengan aman dan damai.', 5),
(NULL, 503, 'e5_n3_s2', 'Aku akan padankan setiap peruntukan Perkara 3 dengan isinya.', 6),
(98, 503, 'e5_n3_s2', 'Cikgu, jadi siapakah sebenarnya Ketua Agama Islam bagi negeri yang tidak mempunyai Raja?', 7),
(88, 503, 'e5_n3_s3', 'Ada orang kata kami penganut agama minoriti tidak bebas beragama. Betulkah?', 1),
(85, 503, 'e5_n3_s3', 'Aku pernah dengar ada Perkara 11 dalam Perlembagaan. Apa isinya?', 2),
(NULL, 503, 'e5_n3_s3', 'Perkara 11 (1) menyatakan tiap-tiap orang berhak menganuti dan mengamalkan agamanya.', 3),
(83, 503, 'e5_n3_s3', 'Perkara 11 (3)(a) pula menyatakan tiap-tiap kumpulan agama berhak menguruskan hal ehwal agamanya sendiri.', 4),
(88, 503, 'e5_n3_s3', 'Jadi kami memang dijamin! Pemuda itu tersilap besar, dan kita perlu tunjukkan kad ini kepadanya.', 5),
(88, 503, 'e5_n3_s3', 'Namun jikalau Perlembagaan telah menjamin hak beragama setiap orang, apakah sikap yang patut kita ambil?', 6),
(98, 503, 'e5_n3_s4', 'Cikgu, rumah ibadat di pameran ini macam kuil semua. Boleh masuk sahaja?', 1),
(87, 503, 'e5_n3_s4', 'Tidak boleh begitu. Setiap rumah ibadat ada adab dan namanya sendiri.', 2),
(84, 503, 'e5_n3_s4', 'Masjid ialah rumah ibadat bagi penganut Islam, dan gereja bagi penganut Kristian.', 3),
(88, 503, 'e5_n3_s4', 'Gurdwara ialah rumah ibadat bagi penganut Sikh, dan kuil bagi penganut Hindu.', 4),
(86, 503, 'e5_n3_s4', 'Wat atau tokong ialah rumah ibadat bagi penganut Buddha, manakala tokong juga rumah ibadat bagi ajaran Konfusius dan ajaran Tao.', 5),
(NULL, 503, 'e5_n3_s4', 'Aku akan cari keenam-enam rumah ibadat itu dan kenal pasti agamanya.', 6),
(89, 503, 'e5_n3_s4', 'Segera, sebelum pengunjung masuk tanpa memahami adab. Jadi sebelum melangkah ke dalam, apa yang patut kita lakukan?', 7),
(84, 503, 'e5_n3_s5', 'Masjid Negara di Kuala Lumpur dirasmikan pada 27 Ogos 1965. Ia boleh menampung 15 000 jemaah.', 1),
(98, 503, 'e5_n3_s5', 'Namun masjid mana yang dibina pada abad ke-18?', 2),
(84, 503, 'e5_n3_s5', 'Masjid Kampung Laut. Ia dibina pada abad ke-18 dan antara masjid tertua di Alam Melayu.', 3),
(84, 503, 'e5_n3_s5', 'Dan Masjid Al-Qadim di Sibu dibina pada 1830 oleh Tuan Haji Salam Minangkabau.', 4),
(NULL, 503, 'e5_n3_s5', 'Masjid Negara, Masjid Kampung Laut dan Masjid Al-Qadim. Aku akan padankan semuanya dengan maklumatnya.', 5),
(83, 503, 'e5_n3_s5', 'Benar. Nah, apakah yang patut kita buat terhadap masjid-masjid lama ini?', 6),
(85, 503, 'e5_n3_s6', 'Gereja St. Michael di Sandakan dibina pada tahun 1893. Ia gereja granit tertua di Malaysia.', 1),
(86, 503, 'e5_n3_s6', 'Wat Boonyaram di Kodiang, Kedah, ialah wat Siam Buddha yang dibina pada 1932.', 2),
(86, 503, 'e5_n3_s6', 'Tokong Cheng Hoon Teng di Melaka dibina pada 1645. Asalnya sebuah kediaman di Awan Hijau.', 3),
(87, 503, 'e5_n3_s6', 'Kuil Sri Rajakaliamman pula ialah kuil kaca pertama dan satu-satunya di Malaysia.', 4),
(88, 503, 'e5_n3_s6', 'Wadda Gurdwara Sahib di Pulau Pinang dibina pada 1901. Seni binanya gabungan Moor dan moden, dan ia kini tapak warisan.', 5),
(NULL, 503, 'e5_n3_s6', 'Aku akan padankan kelima-lima rumah ibadat dengan keistimewaannya.', 6),
(88, 503, 'e5_n3_s6', 'Benar. Selepas engkau mengetahui keistimewaannya, apakah yang boleh kita katakan tentang rumah ibadat bersejarah ini?', 7),
(98, 503, 'e5_n3_s7', 'Cikgu, mengapakah kita perlu menjaga adab di rumah ibadat orang lain?', 1),
(86, 503, 'e5_n3_s7', 'Aku takut tersilap kerana adab di setiap tempat berbeza.', 2),
(89, 503, 'e5_n3_s7', 'Jika tersilap, penganutnya boleh terguris hati.', 3),
(83, 503, 'e5_n3_s7', 'Kad ini menjawab semuanya. Memahami adab dapat menghormati kebebasan beragama kaum lain yang termaktub dalam Perlembagaan Persekutuan.', 4),
(83, 503, 'e5_n3_s7', 'Sesungguhnya, ia juga mengeratkan hubungan silaturahim dan perpaduan, membantu kita mengenali agama lain, dan menunjukkan sifat keperibadian yang terpuji.', 5),
(NULL, 503, 'e5_n3_s7', 'Menghormati kebebasan beragama dan mengeratkan perpaduan. Itulah sebabnya adab penting.', 6),
(98, 503, 'e5_n3_s7', 'Saya faham kini, namun bagaimanakah jikalau ada yang berkata adab itu tidak perlu dijaga?', 7),
(98, 503, 'e5_n3_s8', 'Cikgu, saya telah faham. Namun bagaimanakah hendak merumuskannya dalam syair terakhir?', 1),
(84, 503, 'e5_n3_s8', 'Kita menghormati agama lain agar tidak berbalah.', 2),
(88, 503, 'e5_n3_s8', 'Dan agar persefahaman serta silaturahim terjaga.', 3),
(83, 503, 'e5_n3_s8', 'Menghormati agama lain mengukuhkan rasa persefahaman dalam masyarakat. Menjaga sensitiviti mendidik diri menghormati pelbagai kaum.', 4),
(83, 503, 'e5_n3_s8', 'Mengeratkan silaturahim menjadikan hubungan baik antara kaum. Hidup dalam harmoni menjadikan setiap masyarakat aman dan sejahtera, dan mengelakkan perbalahan bermakna tiada pergaduhan antara kaum.', 5),
(NULL, 503, 'e5_n3_s8', 'Aku akan padankan setiap rumusan dengan alasannya.', 6),
(83, 503, 'e5_n3_s8', 'Nah, itulah bait terakhir syairku. Namun mengapakah hormat kepada kepelbagaian agama begitu penting untuk negara kita?', 7);
INSERT INTO QuestionBank (bankID, eraID) VALUES (5, 5)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(501, 5, 'Antara berikut, yang manakah agama atau ajaran di Malaysia?', 'Ajaran Konfusius', 'Ajaran Miring', 'Ajaran Tamarok', 'Ajaran Magavau', 'A', 'Ingat tujuh agama dan ajaran.', 'Agama dan ajaran: Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Konfusius dan Ajaran Tao.'),
(502, 5, 'Terdapat dua teras kepercayaan dalam agama Islam, iaitu...', 'Al-Quran dan Bible', 'Karma dan Veda', 'Tao dan Analek', 'Rukun Islam dan Rukun Iman', 'D', 'Rukun apa dan rukun apa?', 'Dua teras kepercayaan dalam Islam ialah Rukun Islam dan Rukun Iman.'),
(503, 5, 'Kitab suci agama Islam ialah...', 'Bible', 'Tipitaka', 'al-Quran', 'Veda', 'C', 'Ditambah dengan Hadis.', 'Ajaran Islam berpandukan kitab suci al-Quran dan Hadis.'),
(504, 5, 'Penganut agama Kristian beribadat di gereja pada hari...', 'Jumaat', 'Ahad', 'Sabtu', 'Isnin', 'B', 'Hari yang dikhaskan.', 'Hari Ahad dikhaskan untuk aktiviti keagamaan di gereja.'),
(505, 5, 'Agama Buddha diasaskan oleh...', 'Siddharta Gautama', 'Guru Nanak', 'Lao Tzu', 'Kung Fu Tze', 'A', 'Dikenali sebagai Buddha.', 'Agama Buddha diasaskan oleh Siddharta Gautama.'),
(506, 5, 'Kitab suci agama Buddha ialah...', 'Veda', 'Analek', 'Sri Guru Granth Sahib', 'Tipitaka', 'D', 'Berasaskan Empat Kebenaran Mulia.', 'Kitab suci agama Buddha ialah Tipitaka.'),
(507, 5, 'Penganut agama Hindu mempercayai Hukum Karma yang berkaitan dengan...', 'hasil tanaman', 'cuaca', 'kelakuan manusia semasa hidup', 'bahasa pertuturan', 'C', 'Mereka percaya kelahiran semula.', 'Hukum Karma berkaitan dengan kelakuan manusia semasa hidup dan kelahiran semula.'),
(508, 5, 'Kitab suci agama Hindu dikenali sebagai...', 'Tipitaka', 'Veda', 'Bible', 'al-Quran', 'B', 'Empat huruf.', 'Kitab suci agama Hindu ialah Veda.'),
(509, 5, 'Agama Sikh diasaskan oleh...', 'Guru Nanak', 'Kung Fu Tze', 'Siddharta Gautama', 'Jesus Christ', 'A', 'Penganutnya kaum Sikh.', 'Agama Sikh diasaskan oleh Guru Nanak.'),
(510, 5, 'Tuhan yang dipercayai penganut agama Sikh dinamakan...', 'Petara', 'Kinorohingan', 'Tao', 'Waheguru', 'D', 'Satu Tuhan.', 'Penganut Sikh percaya kepada satu Tuhan bernama Waheguru.'),
(511, 5, 'Ajaran yang menekankan prinsip moral seperti perikemanusiaan dan ketaatan kepada ibu bapa ialah...', 'Ajaran Tao', 'Animisme', 'Ajaran Konfusius', 'Agama Hindu', 'C', 'Terkandung dalam buku Analek.', 'Ajaran Konfusius menekankan perikemanusiaan, kesusilaan dan ketaatan kepada ibu bapa.'),
(512, 5, 'Ajaran Tao diasaskan oleh...', 'Kung Fu Tze', 'Lao Tzu', 'Guru Nanak', 'Siddharta Gautama', 'B', 'Buku Tao Te Ching.', 'Ajaran Tao diasaskan oleh Lao Tzu.'),
(513, 5, 'Ajaran Tao mementingkan keharmonian hidup dengan...', 'alam semesta', 'kekayaan', 'raja', 'peperangan', 'A', 'Tao bermaksud jalan.', 'Penganut Tao percaya kepentingan keharmonian hidup dengan alam semesta.'),
(514, 5, 'Kepercayaan bahawa gua, pokok dan batu besar mempunyai semangat dikenali sebagai...', 'Hukum Karma', 'Kinorohingan', 'Waheguru', 'animisme', 'D', 'Berkaitan roh nenek moyang.', 'Animisme ialah kepercayaan kepada semangat dan roh nenek moyang dalam alam.'),
(515, 5, 'Suku Mah Meri di Pulau Carey mengadakan upacara Puja Pantai untuk...', 'menghalau kuasa jahat daripada badan pesakit', 'memuja Petara', 'mendapatkan perlindungan dan pengampunan daripada semangat laut', 'menjamu tetamu sebagai sedekah', 'C', 'Berkaitan laut.', 'Puja Pantai dilakukan untuk mendapatkan perlindungan dan pengampunan semangat laut.'),
(516, 5, 'Masyarakat Orang Asli suku Temiar dan Semai mengadakan upacara ritual untuk...', 'memuja Petara', 'menghalau kuasa jahat', 'menyambut hasil tuaian', 'memilih ketua kampung', 'B', 'Penyakit disebabkan kuasa jahat.', 'Temiar dan Semai mengadakan upacara ritual untuk menghalau kuasa jahat.'),
(517, 5, 'Masyarakat Iban mempercayai Petara akan menyampaikan petanda melalui...', 'mimpi dan bayangan', 'bunyi gong', 'hujan lebat', 'bintang jatuh', 'A', 'Petara ialah dewa.', 'Petara menyampaikan alamat dan petanda melalui mimpi dan bayangan.'),
(518, 5, 'Upacara Miring dilakukan oleh seorang penyair yang dikenali sebagai...', 'Bobohizan', 'Tok Batin', 'Penghulu', 'Lemambang', 'D', 'Memulakan dengan jampi mantera.', 'Upacara Miring diketuai oleh Lemambang.'),
(519, 5, 'Masyarakat Bisaya mengadakan upacara Tamarok untuk...', 'memanggil semangat padi', 'memanggil roh jahat', 'menghalau kuasa ghaib daripada badan pesakit', 'menyambut tahun baharu', 'C', 'Berkaitan pesakit.', 'Upacara Tamarok menghalau kuasa ghaib daripada badan pesakit.'),
(520, 5, 'Keluarga si mati bagi masyarakat Bajau menjamu tetamu sebagai sedekah dalam upacara...', 'Tamarok', 'Ngeduang', 'Magavau', 'Miring', 'B', 'Diamalkan di Kota Belud.', 'Ngeduang ialah upacara jamuan sedekah oleh keluarga si mati.'),
(521, 5, 'Upacara Mag''ombo oleh Bajau di Semporna bermaksud...', 'menghargai dan menghormati warisan nenek moyang', 'menjamu tetamu sebagai sedekah', 'memanggil semangat padi', 'menghalau kuasa jahat', 'A', 'Di pantai timur Sabah.', 'Mag''ombo bermaksud menghargai dan menghormati warisan turun-temurun.'),
(522, 5, 'Kadazandusun mempercayai Kinorohingan, iaitu...', 'nama kampung', 'penyair upacara', 'alat muzik', 'Tuhan untuk meminta keselamatan dan perlindungan', 'D', 'Berkaitan Tuhan.', 'Kinorohingan ialah Tuhan untuk meminta keselamatan dan perlindungan.'),
(523, 5, 'Ketua bomoh dalam upacara Magavau ialah...', 'Lemambang', 'Tok Batin', 'Bobohizan', 'Petara', 'C', 'Semasa Pesta Kaamatan.', 'Upacara Magavau diketuai Bobohizan.'),
(524, 5, 'Kedudukan agama Islam sebagai agama Persekutuan termaktub dalam...', 'Perkara 11 Perlembagaan Persekutuan', 'Perkara 3 Perlembagaan Persekutuan', 'Perkara 152 Perlembagaan Persekutuan', 'Perkara 160 Perlembagaan Persekutuan', 'B', 'Nombor tiga.', 'Kedudukan agama Islam termaktub dalam Perkara 3 Perlembagaan Persekutuan.'),
(525, 5, 'Siapakah Ketua Agama Islam bagi Kuala Lumpur, Labuan dan Putrajaya?', 'Yang di-Pertuan Agong', 'Perdana Menteri', 'Ketua Hakim Negara', 'Menteri Besar', 'A', 'Perkara 3 (5).', 'Perkara 3 (5): Yang di-Pertuan Agong ialah Ketua Agama Islam bagi Wilayah Persekutuan.'),
(526, 5, 'Siapakah Ketua Agama Islam bagi Melaka, Pulau Pinang, Sabah dan Sarawak?', 'Yang di-Pertua Negeri', 'Ketua Menteri', 'Perdana Menteri', 'Yang di-Pertuan Agong', 'D', 'Perkara 3 (3).', 'Perkara 3 (3): Yang di-Pertuan Agong ialah Ketua Agama Islam di negeri itu.'),
(527, 5, 'Perkara 3 (1) menyatakan Islam ialah agama Persekutuan tetapi...', 'agama lain dilarang', 'hanya satu kaum boleh beragama', 'agama lain boleh diamalkan dengan aman dan damai', 'rumah ibadat lain ditutup', 'C', 'Dalam suasana damai.', 'Agama lain boleh diamalkan dengan aman dan damai di mana-mana bahagian Persekutuan.'),
(528, 5, 'Perkara 11 (1) Perlembagaan Persekutuan menyatakan...', 'Islam ialah agama Persekutuan', 'tiap-tiap orang berhak menganuti dan mengamalkan agamanya', 'Raja ialah Ketua Agama Islam', 'Yang di-Pertuan Agong ialah Ketua Agama Islam', 'B', 'Hak beragama.', 'Perkara 11 (1) memberi hak menganuti dan mengamalkan agama.'),
(529, 5, 'Rumah ibadat penganut Sikh dikenali sebagai...', 'gurdwara', 'kuil', 'wat', 'gereja', 'A', 'Wadda Gurdwara Sahib di Pulau Pinang.', 'Rumah ibadat Sikh ialah gurdwara.'),
(530, 5, 'Rumah ibadat masyarakat Siam beragama Buddha dikenali sebagai...', 'kuil', 'gurdwara', 'masjid', 'wat', 'D', 'Wat Boonyaram di Kodiang.', 'Rumah ibadat masyarakat Siam ialah wat.'),
(531, 5, 'Gereja tertua di negeri Sabah yang merupakan gereja granit tertua di Malaysia ialah...', 'Gereja St. Thomas, Kuching', 'Gereja St. Mary, Kuala Lumpur', 'Gereja St. Michael, Sandakan', 'Gereja St. Paul, Melaka', 'C', 'Dibina pada tahun 1893.', 'Gereja St. Michael di Sandakan dibina pada tahun 1893.'),
(532, 5, 'Tokong Cheng Hoon Teng di Melaka bermaksud...', 'Rumah Cahaya Emas', 'Kediaman di Awan Hijau', 'Istana Langit', 'Gunung Seribu Tahun', 'B', 'Dibina pada 1645.', 'Cheng Hoon Teng bermaksud Kediaman di Awan Hijau.'),
(533, 5, 'Apakah kepentingan memahami adab ketika berada di rumah ibadat?', 'Menghormati kebebasan beragama dan mengeratkan perpaduan', 'Menambah perbalahan antara agama', 'Mengelakkan persefahaman', 'Mengubah agama orang lain', 'A', 'Fikirkan sikap hormat.', 'Memahami adab dapat menghormati kebebasan beragama dan mengeratkan silaturahim dan perpaduan.'),
(534, 5, 'Apakah kepentingan amalan agama dan kepercayaan dalam kehidupan?', 'Masyarakat berbalah dan tiada matlamat', 'Masyarakat tidak berdisiplin', 'Masyarakat terpisah daripada jiran', 'Masyarakat maju, harmoni, berdisiplin dan bermatlamat', 'D', 'Fikirkan hasil positif.', 'Amalan agama menjadikan masyarakat maju, harmoni, berdisiplin dan bermatlamat.'),
(535, 5, 'Seorang pelancong memanggil masjid, kuil dan gurdwara dengan satu nama sahaja. Apakah tindakan murid yang paling sesuai?', 'Membiarkan sahaja kerana semua bangunan itu kelihatan serupa sahaja', 'Menyuruh pelancong itu tidak melawat mana-mana rumah ibadat di sini', 'Menerangkan setiap agama mempunyai nama rumah ibadat tersendiri', 'Menggelakkan pelancong itu di hadapan semua orang yang ada di situ', 'C', 'Ingat nama rumah ibadat setiap agama.', 'Setiap agama mempunyai rumah ibadat yang berlainan, jadi nama dan adabnya perlu diterangkan dengan hormat.'),
(536, 5, 'Murid anda mahu memasuki sebuah kuil tetapi tidak mengetahui adabnya. Apakah langkah yang paling bijak?', 'Masuk dahulu sambil meniru sahaja perbuatan orang lain tanpa bertanya', 'Bertanya kepada penjaga rumah ibadat tentang adab sebelum masuk', 'Menganggap semua rumah ibadat mempunyai adab yang sama seperti rumah kita', 'Membatalkan lawatan itu terus kerana berasa takut tersilap nanti', 'B', 'Fikirkan kebebasan beragama dan perpaduan.', 'Bertanya mengenai adab menunjukkan penghormatan terhadap kebebasan beragama dan mengeratkan perpaduan.'),
(537, 5, 'Sebuah kumpulan agama diganggu ketika menguruskan upacara agamanya. Fasal Perlembagaan manakah yang boleh dirujuk sebagai pembelaan?', 'Perkara 11 (3)(a), iaitu hak menguruskan hal ehwal agama sendiri', 'Perkara 3 (1), iaitu menyatakan bahawa agama lain tidak boleh diamalkan', 'Perkara 3 (5), iaitu Ketua Agama bagi wilayah persekutuan', 'Perkara 3 (2), iaitu kedudukan Raja di negeri berRaja', 'A', 'Fikirkan hak setiap kumpulan agama.', 'Perkara 11 (3)(a) menjamin hak tiap-tiap kumpulan agama untuk menguruskan hal ehwal agamanya sendiri.'),
(538, 5, 'Mengapakah Yang di-Pertuan Agong, bukan Raja, menjadi Ketua Agama Islam bagi Sabah dan Sarawak?', 'Kerana penduduknya semua memeluk agama yang sama', 'Kerana Perlembagaan tidak memberi Raja peranan di Malaysia', 'Kerana Raja-Raja Melayu enggan menjalankan tugas itu', 'Kerana kedua-dua negeri itu tidak mempunyai Raja', 'D', 'Ingat Perkara 3 (2) dan Perkara 3 (3).', 'Raja menjadi Ketua Agama Islam di negeri berRaja, manakala Yang di-Pertuan Agong memegang peranan itu di negeri tanpa Raja seperti Sabah dan Sarawak.'),
(539, 5, 'Upacara Ngeduang di Kota Belud dan Mag''ombo di Semporna berbeza lokasi dan cara. Apakah persamaan yang paling jelas?', 'Kedua-duanya dijalankan semata-mata untuk menghalau penyakit daripada pesakit', 'Kedua-duanya diketuai oleh seorang Lemambang yang melagukan syair', 'Kedua-duanya warisan masyarakat Bajau yang dihormati', 'Kedua-duanya diadakan semasa Pesta Kaamatan oleh masyarakat Kadazandusun', 'C', 'Lihat kaum yang menjalankannya.', 'Ngeduang dan Mag''ombo ialah upacara warisan masyarakat Bajau di pantai barat dan pantai timur Sabah.'),
(540, 5, 'Mengapakah pelbagai agama dapat bertapak di Malaysia sehingga kini?', 'Semua agama dibawa masuk oleh satu kumpulan pedagang sahaja dahulu', 'Agama disebarkan melalui pemerintah, pedagang dan golongan agama', 'Setiap penduduk dipaksa menukar agama mereka oleh pemerintah negeri', 'Agama tersebar secara kebetulan sahaja tanpa melalui sebarang cara tertentu', 'B', 'Ingat tiga pihak yang menyebarkan agama.', 'Agama tersebar melalui peranan pemerintah, pedagang dan golongan agama dengan cara yang aman.'),
(541, 5, 'Rakan anda berkata kepercayaan Orang Asli, Iban dan Bajau tidak perlu dihormati kerana berbeza daripada agama kita. Bagaimanakah anda membalas?', 'Kepercayaan itu warisan nenek moyang mereka dan wajar dihormati', 'Kepercayaan itu perlu ditukar sepenuhnya supaya sama dengan kepercayaan kita', 'Kepercayaan itu hanya penting jika dapat menarik ramai pelancong asing', 'Kepercayaan itu patut diperlekehkan sahaja apabila nampak berbeza daripada kita', 'A', 'Fikirkan hormat kepada kepelbagaian.', 'Setiap kepercayaan ialah warisan masyarakatnya dan mesti dihormati demi hidup yang aman.'),
(542, 5, 'Sebuah masjid abad ke-18 yang menjadi saksi sejarah hampir rosak. Apakah tindakan yang paling bertanggungjawab?', 'Membiarkannya runtuh sendiri kerana bangunan itu sudah terlalu lama', 'Membinanya semula sepenuhnya tanpa mengambil kira sejarah asalnya', 'Melarang semua orang daripada mengetahui sejarah dan asal usulnya', 'Memeliharanya bersama sebagai bukti sejarah dan warisan negara', 'D', 'Ingat Masjid Kampung Laut dan Al-Qadim.', 'Rumah ibadat lama ialah bukti sejarah dan warisan yang perlu dijaga bersama.'),
(543, 5, 'Dua keluarga jiran berlainan agama berselisih tentang bunyi upacara. Tindakan manakah yang menjaga sensitiviti dan mengelakkan perbalahan?', 'Melarang jiran itu menjalankan upacaranya buat selama-lamanya', 'Membalas dengan bunyi yang lebih kuat setiap kali jiran bermula', 'Berbincang dengan hormat dan memahami amalan masing-masing', 'Memutuskan hubungan dan tidak menegur jiran itu lagi selepas ini', 'C', 'Fikirkan persefahaman dan silaturahim.', 'Berbincang dengan hormat mengukuhkan persefahaman, menjaga sensitiviti dan mengelakkan perbalahan antara kaum.');
